\u0023\u003d\u0039\u007c\u0047\u0023\u0039\u0072\u0068\u004a\u002a\u0035\u0079\u0022\u003f\u0065\u003c\u0070\u0041\u002b\u0050\u0042\u004a\u0079\u007a\u0073\u004d\u0061\u0067\u0023\u0063\u0031\u0021\u004c\u003a\u0057\u0051\u0031\u002f\u005d\u0072\u004f\u0028\u0071\u0079\u002c\u0041\u0037\u0028\u004d\u0067\u0033\u006a\u0034\u0056\u0039\u0029\u0077\u0061\u003a\u0055\u0032\u0044\u0041\u0039\u0022\u005e\u0060\u0067\u005d\u003e\u0041\u002a\u006f\u004b\u0044\u002e\u0060\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u0055\u004d\u0070\u0071\u0023\u002b\u006a\u0042\u007c\u003f\u0068\u004a\u0073\u0035\u0059\u003a\u003b\u0070\u004f\u003c\u0033\u0057\u0036\u007e\u0064\u0055\u0075\u0048\u007b\u0074\u004b\u0038\u002b\u0054\u0036\u0071\u0071\u0036\u005e\u0022\u0057\u0069\u0067\u0050\u007d\u0042\u0029\u0064\u0028\u0039\u0073\u004f\u0078\u0025\u006d\u002b\u005d\u0076\u0064\u0033\u003d\u0061\u0054\u0055\u0046\u007c\u004b\u003c\u002c\u0035\u005a\u0054\u002a\u0049\u0033\u0064\u0026\u0053\u0079\u0077\u0037\u0044\u0036\u006f\u0063\u0036\u0057\u0032\u0046\u004d\u004b\u0038\u006a\u003d\u0061\u0049\u005e\u0076\u002b\u0064\u0024\u0072\u003b\u0073\u0036\u0060\u0043\u0061\u006a\u005b\u0053\u002e\u004e\u0076\u0053\u0039\u0074\u0050\u0078\u0069\u005b\u006f\u0050\u007a\u0042\u006a\u0079\u0049\u006c\u0078\u007d\u007e\u004c\u0033\u0059\u002e\u0077\u004a\u0057\u004d\u0046\u0076\u0061\u0076\u0076\u0043\u0023\u0053\u002c\u0069\u0067\u004b\u0054\u0023\u0065\u0062\u0061\u0071\u006c\u0076\u0041\u0076\u0050\u0053\u007e\u0031\u0050\u002b\u006c\u004c\u0059\u005b\u0076\u0070\u0035\u0043\u0078\u0025\u0030\u0029\u0078\u0071\u0032\u0050\u0064\u005e\u005b\u0075\u0039\u0029\u0047\u0068\u0070\u003d\u0030\u0029\u0058\u004f\u0040\u002a\u0050\u0042\u0061\u0022\u0060\u0067\u0034\u003e\u0041\u002a\u0051\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u002c\u0078\u0026\u0069\u002c\u0033\u003d\u0036\u006b\u0068\u0071\u0032\u0063\u0045\u006a\u0024\u0076\u0056\u002c\u0059\u003b\u0068\u0021\u005e\u0023\u007b\u0034\u007a\u0070\u003d\u0030\u0029\u0058\u004f\u003b\u002e\u006c\u0053\u003e\u004b\u0025\u0074\u0047\u005a\u0070\u0048\u0039\u0065\u006c\u0076\u0052\u004e\u0042\u002f\u0055\u0077\u006e\u003f\u0053\u003e\u0079\u006e\u004f\u006a\u004f\u0071\u0072\u0050\u0059\u006f\u006d\u0067\u0059\u0042\u0071\u0032\u0063\u0069\u0033\u004e\u006d\u0070\u0047\u002b\u004c\u0023\u003a\u0055\u0032\u0044\u0041\u0039\u003e\u0067\u0047\u0063\u0044\u0068\u006d\u0074\u007e\u006d\u007b\u0078\u0071\u0036\u0077\u0062\u0040\u0072\u0023\u0041\u0049\u0028\u0072\u0079\u0047\u0025\u0047\u005a\u005f\u0035\u007b\u0029\u002c\u0078\u0047\u0059\u006d\u0028\u0064\u007b\u0066\u0044\u007d\u007e\u0064\u0055\u0033\u0060\u005f\u0035\u0049\u0061\u0031\u006a\u004e\u003f\u0052\u0059\u0059\u006f\u006d\u0067\u0059\u0042\u0071\u0032\u0063\u0069\u0033\u004e\u006d\u0070\u0047\u002b\u004c\u0023\u003a\u0055\u0032\u0044\u005e\u0022\u0041\u0072\u0022\u007b\u0028\u0066\u0041\u002a\u0049\u0034\u0066\u0049\u0029\u0030\u0047\u004e\u005b\u0075\u0025\u0074\u002e\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u006b\u0047\u0032\u002f\u0037\u005e\u0051\u0060\u0055\u0032\u0052\u0035\u0077\u0058\u0041\u004f\u0028\u0065\u006f\u0028\u004b\u005e\u0051\u004a\u0040\u007a\u0058\u004d\u002f\u0039\u0073\u004f\u0078\u0025\u006d\u002b\u007c\u0030\u0033\u0030\u0054\u005e\u004f\u0036\u0039\u0062\u0052\u0066\u0041\u002a\u003d\u007e\u007b\u0034\u0048\u0024\u004c\u0023\u003a\u0055\u0032\u0044\u0041\u0039\u0036\u006a\u0047\u0063\u0067\u006e\u005a\u0048\u002c\u004b\u0076\u0056\u0047\u002b\u002c\u0033\u0037\u0077\u0077\u007b\u0052\u0066\u0055\u004d\u0046\u006a\u003a\u0066\u0076\u0043\u0032\u002f\u0076\u0036\u005b\u004b\u0038\u006e\u0073\u0031\u0052\u0038\u005d\u0066\u006e\u0067\u003b\u002a\u0036\u006a\u0059\u0042\u004b\u003c\u0076\u006a\u003f\u0044\u005b\u006f\u004a\u002a\u0065\u0034\u007d\u0071\u0044\u0024\u0071\u005e\u007a\u0031\u0031\u0073\u0039\u0028\u002f\u004b\u0028\u007e\u0050\u003f\u002f\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u005b\u0076\u0068\u0049\u0025\u0078\u007c\u005e\u004f\u003f\u0052\u0078\u007c\u0032\u006b\u0051\u0028\u0039\u0073\u004f\u0078\u0025\u0054\u0059\u0028\u0071\u0075\u0066\u003c\u0053\u0037\u0048\u0035\u0041\u0055\u0032\u003c\u0045\u0076\u0070\u005b\u0070\u0047\u002b\u003b\u0068\u0048\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0052\u0041\u0058\u0066\u0057\u004d\u0069\u0076\u0025\u0076\u004e\u0047\u0032\u002f\u0053\u0033\u003b\u0073\u0039\u0028\u0030\u0038\u0037\u0033\u0079\u0049\u0069\u0050\u004c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u003a\u0069\u0032\u0073\u003a\u003e\u0052\u0061\u0050\u007e\u0039\u004a\u0038\u002a\u002f\u0072\u004a\u0060\u0029\u005b\u002f\u0068\u0067\u0046\u0052\u0038\u004f\u0071\u0057\u0077\u006a\u0044\u0058\u004f\u0078\u0025\u006e\u006a\u0068\u0049\u0071\u002b\u0033\u0077\u0054\u0075\u0039\u0029\u0060\u005a\u0049\u0035\u004e\u0038\u0060\u0030\u0040\u0076\u004c\u0023\u003a\u0055\u0032\u0044\u005e\u0022\u0076\u0036\u0032\u0073\u0040\u003e\u0041\u002a\u003d\u007e\u007b\u0034\u0040\u0077\u0067\u0044\u0058\u004f\u0078\u0025\u0065\u0034\u0041\u0052\u003e\u005a\u0073\u002f\u0072\u0067\u0023\u004d\u006d\u0023\u004c\u0077\u0028\u007e\u0053\u0052\u0033\u0057\u0036\u007e\u0064\u0055\u0021\u004f\u0068\u003c\u0073\u0050\u0021\u004e\u006c\u0076\u007c\u0065\u0041\u005e\u0074\u0045\u0031\u004d\u006d\u0023\u0043\u0051\u003b\u0065\u006a\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0028\u006e\u003b\u0068\u0065\u0031\u0022\u007b\u0025\u0066\u0041\u002a\u007d\u0076\u0057\u0070\u0076\u0076\u0066\u0075\u004a\u0060\u0032\u0044\u007d\u007e\u0029\u004b\u0029\u003c\u0067\u006e\u0067\u0022\u003d\u006d\u0077\u0071\u0055\u0036\u007d\u007e\u0063\u0036\u0023\u0041\u004f\u004a\u003b\u006e\u0043\u0058\u0073\u0078\u0071\u004e\u003b\u0068\u005d\u0067\u002c\u007c\u005d\u002f\u0045\u0023\u0066\u006a\u0061\u0076\u0031\u0042\u006b\u0065\u0045\u0040\u0030\u0063\u007d\u0042\u0024\u002a\u0038\u0029\u003a\u0078\u0071\u0035\u006b\u0065\u005b\u0055\u003c\u0029\u0023\u0050\u003c\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0060\u006a\u005e\u0052\u007b\u0068\u0035\u005e\u0064\u0022\u007d\u003f\u0039\u0028\u006e\u0026\u0054\u0059\u004b\u003c\u0069\u0069\u0075\u007e\u0045\u0040\u0047\u0062\u0032\u006f\u005f\u0061\u0074\u0076\u003e\u003d\u004e\u0078\u007d\u007e\u0060\u005e\u007a\u0025\u005d\u0043\u0075\u0040\u0063\u006b\u0040\u0064\u003c\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0034\u0034\u0058\u0070\u0071\u004e\u0066\u0075\u007c\u003f\u0041\u007c\u003a\u002f\u0070\u0051\u006d\u0059\u0053\u003e\u0069\u0069\u0053\u0039\u0062\u0056\u0047\u0062\u003f\u0028\u0072\u0079\u0037\u0026\u002b\u002e\u003b\u0043\u007d\u0042\u0064\u007b\u0066\u0044\u007d\u007e\u0064\u0055\u0077\u0074\u004e\u0066\u002c\u0035\u003a\u0076\u0050\u0066\u004c\u004a\u0043\u0053\u006d\u003b\u0050\u002b\u002b\u006f\u004a\u002a\u0054\u0059\u0028\u0071\u0075\u0066\u003c\u0053\u0037\u0048\u0035\u0041\u0055\u0032\u003c\u0045\u0076\u0070\u005b\u0070\u0047\u002b\u003b\u0068\u0048\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0052\u0041\u0058\u0066\u0057\u004d\u0069\u0076\u0025\u0076\u004e\u0047\u0032\u002f\u0053\u0033\u003b\u0073\u0039\u0028\u006a\u0033\u004a\u0034\u007b\u0078\u0035\u0030\u0059\u005e\u0072\u0067\u0069\u0041\u007d\u004a\u0064\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0065\u0034\u0066\u0049\u003f\u004e\u003c\u0053\u0065\u004b\u007b\u0073\u005f\u005a\u0045\u006e\u0050\u007e\u0039\u004a\u0038\u002a\u002f\u0072\u004a\u0060\u0029\u005b\u0042\u0042\u0046\u0074\u004e\u0038\u0038\u0040\u0057\u002b\u0073\u002f\u0039\u0077\u0066\u007e\u005b\u004c\u007c\u002a\u0030\u0029\u0058\u004f\u006b\u0047\u0032\u002f\u0037\u005e\u0076\u0068\u003a\u007a\u0059\u0045\u0054\u0059\u0032\u003e\u0069\u0069\u004c\u0023\u003a\u0055\u0032\u0044\u0077\u0062\u005e\u0072\u003b\u0073\u0044\u0068\u006e\u0074\u002e\u006a\u0032\u002e\u0071\u0036\u005e\u0022\u0045\u0040\u007b\u0035\u0031\u0029\u004a\u002a\u0030\u0029\u007e\u0071\u0078\u002b\u0026\u0053\u003f\u005d\u0051\u004a\u0033\u0032\u004b\u0038\u0063\u0031\u0040\u002e\u0054\u0025\u002b\u004b\u0079\u0034\u004d\u003d\u0059\u0075\u004a\u0060\u0029\u005b\u0042\u0042\u0046\u0074\u004e\u0038\u0038\u0040\u0057\u002b\u0073\u002f\u0039\u0077\u0066\u007e\u0055\u0066\u0043\u0062\u0075\u0065\u0058\u0047\u0059\u0025\u0030\u0029\u0058\u004f\u004e\u0047\u0065\u0075\u0047\u005d\u0039\u0029\u0033\u005a\u0072\u0022\u0043\u004d\u005d\u0076\u002c\u002f\u0055\u005e\u004d\u0075\u004a\u0068\u002e\u0028\u0072\u0079\u0037\u0026\u002b\u002e\u003b\u0043\u005e\u0077\u007c\u0026\u006c\u004b\u0059\u0035\u0032\u0074\u007e\u006f\u0058\u0047\u0059\u0025\u0030\u0029\u0058\u004f\u006b\u0047\u0032\u002f\u0037\u005e\u0076\u0068\u003a\u007a\u0059\u0045\u0054\u0059\u0058\u004a\u0069\u0069\u004c\u0023\u003a\u0055\u0032\u0044\u005e\u0022\u0041\u0072\u0022\u007b\u0028\u0066\u0041\u002a\u0049\u0034\u0066\u0049\u0029\u0030\u0047\u004e\u0068\u0045\u0035\u0041\u0054\u0035\u003c\u006a\u0032\u0046\u0035\u0043\u0021\u0068\u0026\u0053\u0075\u0067\u003a\u007e\u005b\u004c\u007c\u002a\u0030\u0029\u0058\u004f\u0071\u004e\u0063\u0028\u0073\u0077\u0022\u0074\u0039\u0028\u002b\u0068\u007e\u006d\u0041\u0052\u0033\u0057\u0036\u007e\u0064\u0055\u0042\u0049\u004f\u004a\u003e\u0045\u0030\u0029\u0052\u0056\u0039\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u0065\u0034\u0066\u0049\u003f\u004e\u003c\u0053\u0065\u004b\u007b\u0073\u005f\u005a\u0045\u006e\u0050\u007e\u0039\u004a\u0038\u002a\u002f\u0072\u004a\u0060\u0029\u005b\u002f\u0068\u0022\u0048\u004e\u0038\u0030\u004f\u005f\u006b\u0036\u007e\u0064\u0055\u0052\u0078\u007c\u0032\u006b\u0051\u0050\u007e\u0039\u004a\u0033\u0057\u0036\u007e\u0064\u0055\u0021\u004f\u0059\u0035\u007e\u006d\u0065\u0058\u004a\u0056\u006d\u0049\u0077\u0068\u0054\u0055\u0067\u003f\u0057\u0035\u0031\u0046\u0052\u004d\u0032\u003e\u002c\u0025\u0052\u004d\u0032\u003e\u002c\u0025\u0052\u004d\u0032\u003e\u002c\u0025\u002b\u004b\u0079\u0034\u006a\u0039\u003c\u0023\u003a\u0055\u0032\u0044\u0077\u0062\u0041\u0072\u0029\u0039\u007d\u004a\u003b\u006e\u0073\u0034\u0058\u0070\u004c\u0054\u003d\u0061\u0054\u0055\u0060\u0029\u007a\u003c\u005b\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0034\u0034\u0058\u0070\u0071\u004e\u0066\u0075\u007c\u003f\u0052\u0078\u007a\u003c\u006d\u002a\u0052\u007e\u0053\u0052\u0033\u0057\u0036\u007e\u0064\u0055\u003c\u0024\u0077\u004a\u0048\u0048\u0055\u0063\u0028\u0071\u0075\u0066\u005a\u0064\u0054\u0055\u0057\u0041\u0030\u003c\u0035\u0074\u0033\u0071\u0064\u0043\u002c\u006b\u0050\u0033\u0067\u0067\u004d\u0073\u0031\u006d\u0030\u0035\u0033\u004e\u005b\u0070\u004a\u0029\u0077\u0061\u003a\u0055\u0032\u0044\u0077\u0062\u005e\u0072\u003b\u0073\u0044\u0068\u0058\u004d\u004d\u006d\u003a\u0066\u0051\u0026\u0050\u004e\u006a\u0072\u003a\u0032\u0031\u0029\u004a\u002a\u0030\u0029\u007e\u0071\u0078\u002b\u0026\u0053\u003f\u005d\u0051\u004a\u0033\u0032\u004b\u0038\u0063\u0031\u0040\u002e\u0054\u0025\u002b\u004b\u004e\u004a\u0035\u0030\u004c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0053\u0033\u0063\u0039\u0025\u0060\u0037\u0022\u0031\u0033\u0068\u0049\u006b\u0047\u0050\u0053\u0042\u003f\u0077\u0057\u0022\u003c\u0054\u0074\u0033\u0071\u0055\u0078\u0041\u0076\u004c\u0023\u003a\u0055\u0032\u0044\u005e\u0022\u0041\u0072\u0022\u007b\u0028\u0066\u0041\u002a\u0049\u0034\u0066\u0049\u0029\u0030\u0047\u004e\u0068\u0045\u0035\u0041\u0054\u0035\u003c\u006a\u0032\u0046\u0035\u0043\u0021\u0068\u0026\u0053\u0075\u0067\u005f\u007b\u0036\u005a\u0071\u0035\u0071\u006d\u0070\u004f\u005f\u006b\u0036\u007e\u0064\u0055\u0052\u0078\u0068\u003c\u0069\u0048\u0069\u0070\u0060\u0030\u0030\u0076\u0059\u006f\u0023\u0078\u004a\u0029\u004a\u007a\u0070\u003d\u0030\u0029\u0058\u004f\u004c\u004a\u0048\u0064\u005d\u0067\u0078\u0049\u0075\u0035\u0056\u0061\u0064\u0038\u0023\u0066\u006f\u005a\u004c\u0065\u002b\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u007e\u0042\u004f\u005a\u004c\u004d\u0028\u006d\u0075\u0049\u004c\u002c\u0059\u006f\u0024\u0070\u0047\u0062\u003f\u0028\u0072\u0079\u0037\u0026\u002a\u0049\u0042\u0065\u0069\u0075\u007c\u0026\u0066\u0042\u007c\u0032\u0035\u0074\u0048\u005d\u0066\u0049\u0034\u0076\u0032\u002f\u0064\u007b\u0068\u004a\u0068\u003c\u0032\u007a\u003a\u0058\u0041\u004f\u0039\u0035\u007e\u006f\u003e\u004b\u0042\u003e\u0049\u0028\u006c\u0079\u0037\u0026\u002a\u0049\u0042\u0065\u0069\u0075\u007c\u0026\u0066\u0042\u007c\u0032\u0035\u0074\u0038\u0073\u006d\u0070\u002f\u0029\u007d\u0028\u005a\u004b\u0021\u004b\u0068\u003c\u003c\u0045\u0076\u0070\u006a\u0070\u0029\u006e\u004d\u0068\u007c\u004b\u0058\u0029\u0044\u0055\u004b\u0032\u007c\u0023\u0073\u0078\u005f\u0037\u0070\u0068\u0038\u0069\u002c\u0041\u0077\u004a\u0028\u0061\u0045\u0038\u0057\u0070\u0057\u0077\u0040\u0022\u0041\u0072\u0022\u007b\u0028\u0066\u0041\u002a\u006f\u004b\u0044\u002e\u0040\u002b\u002c\u0038\u004b\u003f\u0075\u0048\u0077\u0029\u004b\u0032\u0060\u006a\u0024\u0078\u002c\u0059\u0040\u0022\u0040\u0060\u0032\u0044\u007d\u007e\u0071\u0022\u004a\u003c\u0022\u003c\u0029\u0062\u0077\u0058\u0041\u004f\u0022\u0050\u0073\u002f\u0022\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0062\u0063\u0038\u003e\u0075\u006e\u0040\u006d\u0052\u0071\u0025\u0078\u0050\u0042\u0053\u0033\u0051\u004a\u0068\u003c\u0063\u007d\u006b\u0031\u0068\u0049\u0054\u0025\u0039\u006d\u0062\u0056\u003b\u0043\u004c\u0028\u006c\u0070\u0037\u0044\u0041\u0038\u003f\u005d\u0031\u0035\u0031\u0029\u004a\u002a\u0030\u0029\u0073\u002e\u0060\u002c\u0059\u006f\u007c\u0071\u0047\u0062\u003f\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0029\u0065\u0074\u0075\u004f\u0036\u0050\u007d\u0073\u0035\u0069\u0048\u005d\u006a\u0047\u0071\u0054\u0025\u003d\u007e\u003f\u0056\u0039\u0075\u002e\u0024\u0078\u0060\u0067\u004a\u007d\u004a\u005f\u0035\u0034\u0070\u0035\u0043\u0078\u0025\u0030\u0029\u003d\u0078\u0039\u002c\u0056\u0077\u0075\u0067\u0055\u0059\u0059\u004a\u0057\u004d\u002e\u0058\u0041\u004f\u002a\u0077\u0067\u0044\u0058\u004f\u0078\u0025\u0060\u006a\u004c\u0049\u0076\u0076\u007c\u0061\u0054\u0055\u0036\u007b\u0071\u0032\u0038\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0060\u006a\u004c\u0049\u0076\u0076\u0050\u0053\u0058\u005d\u004d\u0073\u0038\u006e\u0078\u0031\u0050\u007e\u0039\u004a\u0038\u002a\u002f\u0072\u004a\u0060\u0032\u0044\u007d\u007e\u0029\u004b\u0029\u003c\u0067\u006e\u0067\u0022\u003d\u006d\u0077\u0071\u0055\u0036\u0077\u0062\u0069\u0031\u0033\u0060\u002f\u0060\u007d\u0036\u005e\u0062\u0057\u004f\u002b\u005b\u006d\u0065\u002b\u0055\u004c\u006b\u0053\u002f\u0024\u002a\u002b\u004b\u0079\u0034\u006a\u0039\u003c\u0023\u003a\u0055\u0032\u0044\u005e\u0022\u0041\u0072\u0022\u007b\u0028\u0066\u0041\u002a\u0049\u0034\u0066\u0049\u0029\u0030\u0047\u004e\u005b\u0075\u0025\u0074\u002e\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u006b\u0047\u0032\u002f\u0037\u005e\u0076\u0068\u003a\u007a\u0059\u0045\u0076\u0070\u004b\u003c\u0069\u0069\u004c\u0023\u003a\u0055\u0032\u0044\u0077\u0062\u005e\u0072\u003b\u0073\u0044\u0068\u006e\u0074\u002e\u006a\u0032\u002e\u0071\u0036\u005e\u0022\u0045\u0040\u007b\u0035\u0031\u0029\u004a\u002a\u0030\u0029\u0072\u0078\u003b\u0050\u0054\u0075\u0047\u005d\u0039\u0029\u007a\u0032\u0039\u004d\u0072\u0038\u006d\u0070\u003c\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u0061\u0058\u0073\u0078\u0054\u0064\u0073\u002f\u0076\u0036\u003c\u0067\u0073\u0028\u006e\u0026\u0039\u0063\u0032\u003e\u0066\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u005b\u0076\u0068\u0049\u0025\u0078\u007c\u005e\u004f\u003f\u0052\u0078\u007c\u0032\u006b\u0051\u0028\u0039\u0073\u004f\u0078\u0025\u0054\u0059\u0028\u0071\u0075\u0066\u003c\u0053\u0037\u0048\u0035\u0041\u0055\u0032\u003c\u0045\u0076\u0070\u005b\u0070\u0047\u002b\u003b\u0068\u0048\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0052\u0041\u0058\u0066\u0057\u004d\u0069\u0076\u0025\u0076\u004e\u0047\u0032\u002f\u0053\u0033\u003b\u0073\u0039\u0028\u0030\u0038\u0037\u0033\u0079\u0049\u0069\u0050\u004c\u0023\u0079\u0021\u0025\u0072\u0049\u0035\u0049\u0035\u0073\u0058\u004a\u0078\u0053\u002b\u0039\u0064\u0053\u0033\u0064\u0035\u0032\u006f\u0037\u0022\u0031\u0033\u0068\u0049\u006b\u0047\u0050\u0053\u0042\u003f\u0068\u004a\u002a\u0035\u0071\u0035\u003f\u0065\u0079\u0034\u0077\u0022\u0073\u0058\u0061\u003f\u0075\u0048\u0077\u0029\u005f\u0038\u0052\u0038\u004f\u0071\u007e\u0069\u0040\u0022\u0077\u0055\u0074\u007b\u007c\u0032\u0079\u0022\u0050\u007e\u0053\u0059\u007e\u002f\u0070\u0031\u0044\u0031\u007e\u0032\u006d\u0023\u0069\u003d\u0033\u0070\u005b\u0070\u007b\u0078\u0064\u0033\u0048\u0055\u0032\u007e\u0049\u0035\u002a\u0035\u002e\u0058\u0023\u0066\u0031\u0042\u0025\u0068\u0024\u0071\u006a\u0070\u0039\u0035\u0041\u002a\u0044\u0057\u004a\u0034\u003d\u0076\u003a\u002f\u005b\u0053\u0024\u0068\u0030\u003c\u0076\u006a\u003b\u0024\u0055\u0078\u0043\u0053\u002f\u0064\u0078\u0072\u005e\u0067\u005b\u004a\u0041\u002a\u0033\u006a\u0064\u0078\u0074\u0024\u006b\u0065\u0030\u0030\u0037\u0044\u006a\u004e\u0066\u0049\u0037\u0044\u0041\u0038\u0032\u002e\u0037\u0044\u0055\u0038\u004e\u0070\u0048\u0050\u002e\u0028\u006c\u0079\u0037\u0026\u0051\u0078\u0051\u0078\u0038\u0064\u003f\u0022\u004a\u003c\u0059\u004a\u0056\u0035\u0052\u0038\u0070\u004f\u0053\u0029\u0078\u0075\u0063\u0036\u003b\u0073\u0077\u004a\u003b\u006e\u0021\u0033\u006d\u0070\u0047\u002b\u003d\u0061\u0054\u0055\u0036\u007b\u0071\u0032\u0038\u006a\u0034\u005d\u003a\u0056\u002c\u002f\u0073\u002f\u0071\u0079\u0039\u0029\u0052\u0042\u003c\u0077\u0064\u007e\u0044\u005f\u0055\u0057\u0050\u0033\u0067\u0067\u004d\u0073\u0054\u005a\u004d\u002a\u006a\u0058\u0073\u004f\u0078\u0025\u0071\u002c\u006d\u0070\u0068\u002b\u002a\u004e\u0066\u0077\u006e\u003f\u0030\u003c\u0041\u002a\u0046\u0054\u0036\u0071\u005e\u0076\u0074\u0075\u004a\u0060\u0032\u0044\u007d\u007e\u007d\u0033\u003c\u0067\u0047\u005a\u006c\u0033\u0059\u0058\u0035\u0070\u0054\u0025\u006a\u0070\u003f\u0056\u0039\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u004f\u006a\u004f\u0071\u0072\u0050\u0059\u006f\u0060\u006a\u0070\u0063\u004f\u0074\u0038\u006e\u006f\u006d\u007b\u0049\u0040\u0059\u003d\u0033\u004a\u0060\u0032\u0044\u007d\u007e\u0069\u0077\u0070\u0063\u003e\u006e\u0039\u005a\u002a\u0073\u0076\u0056\u0038\u002b\u0058\u0053\u0042\u003f\u0041\u007c\u0047\u0042\u0070\u0051\u0028\u0039\u0073\u004f\u0078\u0025\u0071\u002c\u007c\u0030\u0039\u0076\u0025\u0043\u006b\u0033\u006e\u003f\u0053\u003e\u0066\u0045\u0054\u0059\u0055\u0034\u003a\u0077\u002e\u0024\u0078\u0060\u0067\u004a\u005f\u005a\u006d\u0048\u006a\u0071\u0041\u0034\u002b\u004e\u0032\u002f\u0064\u007b\u0068\u004a\u0068\u003c\u0032\u007a\u003a\u0058\u0041\u004f\u0073\u004a\u0044\u002f\u0075\u002e\u0078\u0059\u0049\u0028\u002b\u0068\u0030\u0031\u0079\u0049\u003e\u005a\u0071\u005e\u007a\u0031\u0031\u0073\u0039\u0028\u0038\u0075\u0028\u007e\u0036\u0066\u0079\u0067\u003b\u002a\u0044\u0067\u0034\u0042\u0047\u005a\u0078\u0031\u0065\u0062\u0034\u0056\u0041\u0076\u0040\u0022\u0077\u0055\u0074\u007b\u007c\u0032\u0079\u0022\u0050\u007e\u0053\u0059\u0044\u003e\u0031\u0038\u0055\u0071\u0065\u0032\u0054\u006f\u006d\u007a\u0072\u0038\u006c\u0076\u0078\u0076\u0033\u0077\u0071\u0048\u0036\u004d\u006d\u0023\u0036\u0026\u0051\u0070\u0041\u004f\u002c\u006b\u0050\u0033\u0067\u0067\u004d\u0073\u0054\u005a\u0041\u005a\u0045\u004e\u0073\u0078\u0057\u0029\u007d\u0028\u005a\u004b\u0021\u004b\u0068\u003c\u003c\u0045\u0076\u0070\u002c\u0078\u0024\u007c\u0072\u0033\u0055\u0071\u0058\u0029\u0037\u0035\u0057\u005a\u0078\u006d\u0045\u003f\u0056\u004e\u0042\u002f\u0051\u0067\u0039\u0029\u006e\u002f\u0033\u0026\u0064\u007e\u0044\u005f\u0055\u0057\u0050\u0033\u0041\u0072\u003b\u0073\u0059\u005a\u002a\u0035\u007c\u006f\u0058\u0047\u0059\u0025\u0030\u0029\u0058\u004f\u0071\u004e\u0063\u0028\u0073\u0077\u0022\u0074\u0039\u0028\u002b\u0068\u007e\u006d\u0041\u0052\u0033\u0057\u0036\u007e\u0064\u0055\u0042\u0049\u004f\u004a\u003e\u0045\u0030\u0029\u0052\u0056\u0039\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u0065\u0034\u0066\u0049\u003f\u004e\u003c\u0053\u0065\u004b\u007b\u0073\u005f\u005a\u0045\u006e\u0050\u007e\u0039\u004a\u0050\u002a\u002f\u0072\u004a\u0060\u0029\u005b\u0042\u0042\u0035\u0048\u0075\u0065\u0058\u0047\u0059\u0025\u0030\u0029\u0058\u004f\u005d\u0078\u006a\u0042\u004f\u003f\u0041\u007c\u0030\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0039\u0047\u006f\u0028\u0057\u0033\u0022\u004d\u0054\u006f\u005a\u007a\u0028\u006d\u005d\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0039\u0047\u006f\u0028\u0057\u0033\u005b\u007d\u0060\u005a\u0076\u0050\u0067\u0054\u0064\u0049\u0054\u0025\u003d\u007e\u003f\u0056\u0039\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u0034\u0034\u0058\u0070\u0071\u004e\u0066\u0075\u007c\u003f\u005a\u002a\u007a\u003c\u006d\u002a\u0051\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u006a\u0070\u0061\u0049\u0026\u0053\u0044\u0067\u0074\u004d\u0077\u004a\u0041\u002a\u0054\u0073\u003f\u0056\u0039\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u0024\u006a\u007d\u0071\u0075\u0030\u006c\u0053\u004f\u0036\u0039\u0062\u0052\u0066\u0041\u002a\u0071\u007e\u007b\u0034\u0033\u0057\u0036\u007e\u0064\u0055\u0068\u004a\u004d\u0066\u0040\u0031\u002e\u0058\u0023\u0066\u0040\u002a\u0058\u0053\u005b\u0075\u0035\u0041\u004f\u005a\u0070\u003d\u0030\u0029\u0058\u004f\u0046\u0046\u0050\u0053\u002b\u0075\u0076\u0068\u0047\u005a\u0035\u007a\u0053\u0058\u0041\u004f\u006a\u0056\u007d\u004e\u007e\u0067\u0050\u002b\u006c\u004c\u004b\u0032\u006b\u0038\u0077\u0071\u003f\u0043\u0026\u0042\u0076\u0036\u007a\u0041\u0032\u0023\u0035\u002a\u0061\u0058\u0073\u0078\u0054\u0064\u0062\u0077\u0047\u005d\u0054\u004d\u006d\u0023\u0072\u0038\u004e\u0038\u0054\u0070\u003f\u002a\u0050\u004e\u0077\u0071\u0031\u0035\u006d\u0023\u0069\u003d\u003a\u0073\u003b\u0049\u0033\u0030\u0051\u0064\u003d\u0036\u007e\u0042\u004f\u005a\u006d\u002a\u0030\u006f\u002c\u0078\u002c\u002f\u0021\u0077\u003f\u005d\u0074\u0041\u0071\u003c\u0059\u0045\u003b\u0069\u0073\u0078\u004b\u0024\u0047\u004e\u005e\u0069\u006f\u003c\u007d\u004a\u0069\u0048\u0074\u0070\u0041\u004f\u004e\u0047\u0065\u0075\u0047\u005d\u0039\u0029\u004a\u0050\u0030\u0048\u0046\u0073\u005a\u004a\u002c\u0077\u0041\u0039\u0078\u0060\u0046\u003b\u0030\u0060\u006f\u004a\u0058\u003d\u0044\u0073\u002e\u0050\u005e\u0048\u003b\u002a\u0057\u0073\u0035\u0023\u0068\u0057\u0079\u003a\u0022\u0039\u0023\u0066\u0075\u0062\u0076\u0040\u0025\u0072\u007e\u0032\u0037\u002c\u006d\u0054\u0066\u0049\u0039\u0047\u0074\u0068\u004d\u0022\u0064\u0035\u0077\u0029\u004a\u002a\u0030\u0029\u002c\u0078\u002c\u002f\u0021\u0077\u003f\u005d\u0074\u0041\u0071\u003c\u0059\u0045\u006a\u0024\u0078\u002e\u0067\u0043\u0023\u0043\u0060\u005e\u007a\u0025\u005d\u0043\u0075\u0040\u0037\u0044\u0055\u0038\u0025\u0070\u0031\u0035\u0031\u0029\u004a\u002a\u0030\u0029\u002c\u0078\u0072\u0050\u0041\u005e\u003f\u005d\u0055\u0059\u0059\u004a\u0066\u004d\u006a\u0071\u0023\u0066\u0034\u003a\u004c\u0065\u0032\u003b\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0073\u0078\u0053\u0059\u0039\u0064\u0026\u0031\u0039\u0029\u0051\u002f\u0070\u0051\u0028\u0039\u0073\u004f\u0078\u0025\u006d\u002b\u0024\u0078\u0067\u0030\u0054\u005e\u004f\u0036\u0039\u0062\u0052\u0066\u0041\u002a\u0030\u0063\u007b\u0034\u0069\u0069\u004c\u0023\u003a\u0055\u0032\u0044\u005e\u0022\u004e\u006a\u0047\u0063\u0029\u003e\u0032\u007a\u002c\u006d\u0061\u0052\u0054\u0025\u003a\u0054\u007b\u0049\u0034\u0075\u0067\u0044\u0058\u004f\u0078\u0025\u0060\u006a\u004c\u0049\u0076\u0076\u007c\u0061\u0054\u0055\u0060\u0029\u0034\u004c\u006a\u0033\u0045\u0038\u007c\u0030\u002f\u0029\u0023\u0075\u003e\u004b\u0063\u0062\u007d\u0068\u0077\u0036\u0079\u0029\u002b\u004a\u0054\u005b\u005d\u0043\u0024\u0070\u0058\u006b\u0022\u0060\u006e\u0026\u007e\u007e\u0032\u003e\u0030\u0077\u002e\u0024\u0078\u0060\u003a\u0069\u0057\u0035\u0070\u0048\u004d\u0038\u0059\u0071\u0028\u0029\u0077\u0061\u003a\u0055\u0032\u0044\u0077\u0062\u005e\u0072\u003b\u0073\u0044\u0068\u0058\u004d\u004d\u006d\u003a\u0066\u0035\u0022\u0050\u004e\u006a\u0072\u003a\u0032\u0031\u0029\u004a\u002a\u0030\u0029\u0077\u0049\u002b\u0069\u0026\u0053\u0032\u0067\u0059\u0042\u0071\u0032\u0060\u0064\u002e\u0058\u005f\u0071\u0054\u0025\u0063\u006f\u0038\u0056\u0069\u0050\u0055\u005e\u0063\u0067\u0028\u0032\u0031\u0029\u004a\u002a\u0030\u0029\u007e\u0071\u0078\u002b\u0026\u0053\u003f\u005d\u0051\u004a\u0033\u0032\u004b\u0038\u0063\u0031\u0040\u002e\u0054\u0025\u002b\u004b\u0079\u0034\u0035\u003d\u0059\u0075\u004a\u0060\u0032\u0044\u007d\u007e\u005a\u004b\u0021\u004b\u0068\u003c\u003c\u0045\u003b\u0069\u0073\u0078\u004b\u0024\u0047\u004e\u005e\u0069\u006f\u003c\u007d\u004a\u0069\u0048\u0074\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0078\u0071\u0032\u0050\u0064\u005e\u005b\u0075\u0055\u0059\u0068\u003c\u0033\u0048\u003d\u006d\u0038\u0066\u0046\u0046\u0072\u002f\u007d\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u004d\u007b\u0030\u003c\u0079\u006e\u002a\u006d\u006f\u0030\u004d\u0024\u0055\u0061\u0054\u0055\u003c\u0029\u005f\u0068\u0070\u003d\u0030\u0029\u0058\u004f\u0046\u0046\u006a\u0042\u006a\u0067\u0046\u007c\u007c\u0032\u0056\u0061\u0053\u0058\u0041\u004f\u003d\u0076\u0032\u002f\u0053\u0033\u002e\u0032\u0048\u002c\u0069\u003d\u0043\u0062\u0061\u0078\u0036\u0039\u0026\u0053\u0079\u0077\u0064\u0035\u0077\u0029\u004a\u002a\u0030\u0029\u003c\u0070\u0061\u0064\u005d\u002f\u0062\u0069\u003b\u004d\u0054\u006f\u003f\u0035\u003f\u0065\u006a\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0055\u0054\u0063\u0028\u0076\u0036\u005d\u0074\u0044\u0068\u005b\u007a\u0072\u0038\u006d\u0070\u0047\u002b\u0059\u006f\u0037\u005d\u0042\u0042\u005f\u0035\u0075\u006e\u0074\u0054\u003b\u0049\u0078\u0076\u003b\u0068\u0031\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u004d\u007b\u0030\u003c\u0079\u006e\u0057\u0034\u0065\u0047\u0024\u0036\u0041\u0039\u0067\u0040\u0047\u0062\u003f\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0065\u0065\u007d\u0042\u004f\u0036\u0048\u003f\u0073\u0028\u006a\u0033\u003b\u0065\u0071\u004f\u0061\u002a\u002f\u0072\u004a\u0060\u0032\u0044\u007d\u007e\u0029\u004b\u006e\u0063\u006d\u0035\u005d\u0022\u002a\u0073\u0076\u0056\u0038\u002b\u0058\u0053\u0042\u003f\u0041\u007c\u007a\u003c\u006d\u002a\u007d\u006a\u004f\u0071\u0030\u0059\u0072\u0062\u0069\u0031\u0033\u0060\u002f\u0060\u007d\u0036\u005e\u0062\u0057\u004f\u002b\u005b\u006d\u0065\u002b\u0055\u004c\u006b\u0053\u002f\u0024\u002a\u002b\u004b\u0079\u0034\u0067\u0039\u003c\u0023\u003a\u0055\u0032\u0044\u005e\u0022\u0041\u0072\u0022\u007b\u0028\u0066\u0041\u002a\u0049\u0034\u0066\u0049\u0029\u0030\u0047\u004e\u0068\u0045\u0035\u0041\u0054\u0035\u003c\u006a\u0032\u0046\u0035\u0043\u0073\u0078\u003d\u005e\u0037\u0048\u0035\u0041\u004c\u003c\u003c\u0035\u0043\u0071\u007b\u0049\u0079\u0042\u0035\u005e\u0055\u0077\u003e\u007e\u005b\u004c\u0044\u003a\u002e\u0058\u006b\u0070\u0069\u0050\u0044\u0038\u0041\u0072\u006f\u0039\u0061\u0032\u0034\u0045\u003b\u0069\u0034\u0056\u0039\u0076\u0066\u006f\u0044\u0037\u0025\u0072\u0029\u003c\u0077\u006e\u0079\u0038\u0064\u0049\u0057\u0077\u0040\u0022\u0041\u0072\u0022\u007b\u0028\u0066\u0041\u002a\u006f\u004b\u0044\u002e\u0040\u002b\u002c\u0038\u004b\u003f\u0052\u0078\u0068\u003c\u0069\u0048\u004b\u005d\u006d\u0070\u0075\u0066\u0034\u002f\u0028\u003f\u0021\u004f\u0068\u003c\u004c\u0050\u0061\u007e\u0044\u005f\u005d\u0072\u0054\u0033\u0067\u0067\u0034\u0022\u007d\u004a\u0030\u003d\u003f\u002a\u0055\u0070\u0065\u006e\u0040\u0022\u0066\u0077\u0029\u003c\u0057\u005a\u003d\u003a\u0026\u0058\u0073\u0078\u0072\u007c\u0047\u0023\u0066\u0052\u0077\u0074\u0036\u0066\u0030\u0038\u0029\u0034\u0074\u0049\u0075\u0045\u0062\u0022\u003f\u0048\u0026\u004b\u006f\u003c\u002e\u0021\u007b\u0055\u0073\u004f\u0078\u0025\u0071\u002c\u0055\u0070\u0065\u006e\u0040\u0022\u0066\u0077\u0029\u003c\u0057\u005a\u003d\u003a\u0077\u0054\u0055\u0078\u007a\u007c\u0047\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u004e\u006f\u004f\u0036\u0064\u007e\u0056\u004a\u0029\u0062\u007d\u0071\u0061\u004c\u005d\u0055\u0071\u005e\u0064\u0022\u005f\u007b\u0052\u005a\u005a\u0048\u007e\u006d\u0042\u0059\u0057\u007c\u005d\u0063\u0067\u0055\u003e\u003e\u0033\u0032\u004c\u005a\u0069\u0062\u0033\u0039\u002c\u0051\u0054\u0033\u0060\u0051\u0045\u005d\u0037\u0028\u0057\u0057\u002b\u002e\u005e\u004f\u0028\u0064\u0070\u0053\u002b\u0075\u0051\u0024\u0021\u004d\u0022\u003b\u007d\u0070\u0038\u0056\u003f\u0049\u005f\u006f\u0066\u0040\u0077\u0074\u0036\u0066\u0030\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006a\u004f\u0039\u0064\u007d\u0055\u006e\u004b\u0059\u0035\u0040\u0031\u003e\u0039\u0046\u002e\u003b\u0043\u005e\u0077\u007c\u0026\u006c\u004b\u0059\u0035\u0032\u0074\u003a\u0058\u0075\u004c\u003c\u0069\u0065\u0072\u0052\u0057\u005e\u0039\u006a\u002b\u002b\u002b\u006f\u004a\u002a\u0071\u002c\u0061\u0034\u0071\u004e\u0071\u0061\u003e\u0060\u0066\u0044\u007d\u007e\u0064\u0055\u007d\u0024\u003a\u003e\u0054\u002a\u0040\u0038\u0024\u0078\u005a\u0064\u0030\u0023\u0037\u005d\u0034\u0042\u0047\u005a\u003f\u003a\u004c\u0039\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u005b\u0062\u006f\u0030\u0058\u0029\u005a\u0042\u0062\u0069\u0030\u003c\u0048\u0028\u003b\u0033\u0040\u0034\u003b\u0049\u0022\u003b\u0067\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006a\u004f\u0039\u0064\u007d\u0055\u006e\u004b\u0059\u0035\u0040\u0031\u003e\u0039\u005f\u0049\u0042\u0065\u0069\u0075\u007c\u0026\u0044\u0042\u0057\u0035\u0049\u0035\u007e\u004b\u0078\u005e\u0058\u0054\u006f\u0028\u0053\u0046\u0060\u0068\u0030\u003c\u0078\u0031\u0071\u0067\u0066\u0070\u0065\u006e\u002a\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0066\u0069\u002b\u0035\u003a\u0077\u0034\u0070\u0028\u0071\u0062\u0064\u005b\u0053\u0060\u0073\u0043\u0039\u0059\u004a\u0055\u005f\u0032\u0033\u0073\u0078\u0073\u0054\u006a\u0042\u003a\u0031\u0021\u004b\u005b\u004a\u003e\u002a\u002b\u0038\u0068\u004c\u003f\u005b\u005b\u0053\u003f\u005d\u003d\u007b\u003a\u003e\u0069\u0048\u0074\u0058\u0075\u004c\u0038\u0073\u0079\u0030\u0033\u0062\u0072\u0052\u0057\u005e\u0039\u006a\u002b\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0067\u0066\u0070\u0065\u006e\u002a\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u004e\u006f\u004f\u0036\u0064\u007e\u0056\u004a\u0029\u0062\u007d\u0071\u0061\u004c\u007d\u0068\u0026\u0053\u0075\u0067\u0062\u0051\u0031\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u005b\u0062\u006f\u0030\u0058\u0029\u005a\u0042\u0062\u0069\u0030\u003c\u0048\u0028\u003b\u0033\u0040\u0034\u003b\u0049\u0024\u0037\u007e\u0053\u004a\u004b\u0026\u004b\u0065\u007c\u006e\u0053\u0063\u0031\u0068\u0049\u0072\u0055\u0058\u004e\u006c\u0057\u005a\u0079\u0046\u0035\u003a\u0077\u0055\u0039\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u004f\u0051\u0057\u005e\u0039\u006a\u0068\u004a\u007c\u0032\u0073\u0031\u0041\u006d\u0043\u0059\u003a\u002b\u0050\u0042\u0059\u0026\u0075\u0070\u0059\u004a\u0063\u007d\u003f\u0065\u0073\u002e\u006b\u0076\u003b\u0068\u003c\u0073\u005e\u0050\u0054\u0035\u003d\u003a\u005f\u0034\u007d\u0071\u0067\u007c\u0052\u006f\u0041\u0052\u0038\u0024\u003a\u003e\u0072\u0021\u0049\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u004f\u0051\u0063\u0065\u004f\u0036\u0040\u0067\u0031\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0071\u002c\u0055\u0070\u0065\u006e\u0040\u0022\u0066\u0077\u0029\u003c\u0057\u005a\u003d\u003a\u007c\u0023\u0073\u0078\u0045\u007c\u0047\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0066\u0069\u002b\u0035\u003a\u0077\u0034\u0070\u0028\u0071\u0062\u0064\u005b\u0053\u0060\u0073\u0043\u0039\u0059\u004a\u0055\u005f\u003e\u0038\u0024\u0078\u0063\u0076\u0038\u0064\u006e\u0047\u007c\u007b\u0058\u005a\u006d\u0074\u007c\u006f\u0028\u003d\u0043\u004e\u002b\u0043\u0066\u0040\u0077\u0074\u0036\u0066\u0030\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0063\u004c\u0071\u004e\u0030\u0028\u005a\u004b\u0044\u0042\u0058\u005a\u0056\u007b\u0024\u0070\u007b\u0049\u0041\u002b\u0045\u007d\u0055\u006a\u005b\u004b\u005b\u005a\u0050\u002a\u0039\u006d\u0058\u0070\u002e\u0025\u002b\u0038\u0068\u004c\u0059\u0078\u0057\u0075\u004a\u0067\u002f\u003c\u006f\u007c\u0072\u0026\u0030\u0067\u0066\u0070\u0065\u006e\u002a\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0048\u0031\u003f\u0022\u007c\u002e\u006c\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0072\u0052\u0057\u005e\u0039\u006a\u002b\u002b\u004b\u0029\u004a\u002a\u0030\u0029\u0063\u004c\u0071\u004e\u0030\u0028\u005a\u004b\u0044\u0042\u0058\u005a\u0056\u007b\u0044\u0073\u0076\u0056\u0032\u0050\u0077\u0068\u0064\u0055\u0036\u0073\u0031\u0028\u0029\u003a\u0063\u0034\u0066\u0049\u007a\u007c\u0047\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0029\u0030\u002c\u0075\u0053\u0062\u0061\u004a\u0036\u004e\u007c\u006b\u0028\u0045\u0067\u003c\u0067\u0032\u0023\u0056\u0035\u0043\u0071\u0064\u0049\u0058\u007c\u0066\u005e\u004c\u0077\u002b\u0063\u005b\u006f\u0037\u002c\u0040\u0034\u0021\u0076\u0038\u0049\u0041\u005e\u006d\u003b\u0064\u0059\u007e\u005f\u0065\u0026\u0061\u0056\u006b\u006a\u0074\u0039\u0052\u004d\u007b\u0047\u007b\u0042\u0035\u0048\u0046\u007d\u0023\u0059\u0025\u0030\u0029\u0058\u004f\u0072\u0052\u0057\u005e\u0039\u006a\u002b\u002b\u004b\u0029\u004a\u002a\u0030\u0029\u0063\u004c\u0071\u004e\u0030\u0028\u005a\u004b\u0044\u0042\u0058\u005a\u0056\u007b\u0024\u0070\u007b\u0049\u0041\u002b\u0077\u0075\u0066\u0073\u005e\u0050\u0054\u0035\u003d\u003a\u007c\u0023\u0073\u0078\u0053\u0054\u003d\u0061\u006e\u0047\u0053\u007b\u004d\u0066\u004d\u002a\u0040\u006d\u0055\u0049\u003c\u0029\u003a\u0043\u0060\u006b\u0029\u0029\u0041\u0054\u0039\u005a\u0056\u002c\u004a\u0056\u0065\u0066\u006a\u0042\u007d\u0055\u0060\u006b\u0054\u006f\u0023\u007a\u0063\u0031\u0079\u0049\u0060\u0065\u0048\u0031\u003f\u0022\u007c\u002e\u006c\u0028\u004f\u003d\u0030\u0029\u0058\u004f\u004f\u0051\u0057\u005e\u0039\u006a\u0068\u004a\u007c\u0032\u0073\u0031\u0041\u006d\u0043\u0059\u004e\u0047\u0032\u002f\u002a\u005d\u0021\u004b\u004e\u0066\u002e\u0021\u0049\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u004f\u0051\u0059\u005e\u0045\u0067\u007b\u007b\u0030\u003c\u0030\u0038\u0029\u0034\u0074\u0049\u0075\u0045\u0029\u003a\u0075\u0067\u0071\u007e\u0024\u004a\u005e\u005a\u0025\u0029\u0055\u0049\u007a\u0030\u0074\u0068\u0030\u0079\u0069\u0044\u0055\u002f\u0034\u0047\u0044\u0059\u0052\u0066\u0058\u0066\u0066\u006a\u004f\u0039\u004d\u0030\u003b\u0068\u006e\u0047\u006d\u006c\u004f\u004e\u0026\u002a\u003a\u003a\u0024\u0078\u0041\u0029\u0055\u0048\u002a\u0069\u0060\u0067\u002b\u0061\u0060\u003a\u0076\u0023\u007b\u0049\u0061\u0049\u002a\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0066\u0040\u0077\u0074\u0036\u0066\u0030\u003d\u0049\u0044\u005b\u006f\u004a\u002a\u0067\u0063\u0051\u0076\u0062\u0025\u0061\u005b\u007b\u0055\u0036\u003d\u0055\u0074\u0026\u0061\u0035\u0059\u0029\u0059\u0057\u0057\u005f\u0043\u0040\u004f\u0023\u002a\u0041\u0039\u0022\u005e\u002b\u002b\u002b\u006f\u004a\u002a\u0071\u002c\u0055\u0070\u0065\u006e\u0040\u0022\u0066\u0077\u0029\u003c\u0057\u005a\u003d\u003a\u0029\u006d\u0055\u0078\u0076\u0076\u007c\u0061\u0041\u0072\u0070\u0063\u0054\u004a\u002e\u0021\u0049\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u004f\u0051\u0057\u005e\u0039\u006a\u0068\u004a\u007c\u0032\u0073\u0031\u0041\u006d\u0043\u0059\u0036\u007c\u0025\u0043\u0076\u0036\u007c\u0022\u007d\u004a\u002e\u0021\u006b\u006c\u002a\u0023\u0047\u0029\u006a\u0036\u007c\u0051\u0041\u007c\u0047\u0042\u006f\u004a\u0032\u0076\u0058\u0070\u0069\u0050\u0076\u0077\u0062\u0069\u0029\u0039\u002b\u0061\u0067\u0023\u0063\u0031\u0021\u004c\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0063\u004c\u0071\u004e\u0030\u0028\u0079\u0048\u005e\u007d\u0029\u007c\u0071\u003a\u0061\u003d\u0068\u0049\u0045\u007c\u0047\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0037\u0065\u0061\u006c\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0063\u004c\u0022\u004f\u0039\u0064\u003b\u0047\u0066\u0044\u007d\u007e\u0064\u0055\u005a\u0079\u0046\u0035\u003a\u0077\u0055\u0039\u003a\u0043\u0072\u0052\u0057\u005e\u0039\u006a\u002b\u002b\u0050\u0061\u0067\u0023\u0063\u0031\u0021\u004c\u0055\u0057\u0031\u0031\u0079\u004b\u0063\u0068\u004b\u003c\u0075\u0021\u0052\u0025\u0037\u0035\u005e\u005a\u0078\u0038\u0060\u0030\u0061\u0049\u006f\u004e\u0046\u0055\u0037\u004d\u002b\u006f\u004a\u002a\u0071\u002c\u0054\u0070\u0039\u0029\u0063\u0077\u0062\u0069\u0029\u0039\u0032\u0023\u005e\u002a\u0040\u0039\u0055\u0049\u002e\u0033\u006f\u004e\u0025\u0057\u0022\u0078\u003a\u003e\u005f\u0035\u004e\u004b\u004e\u003f\u007b\u0078\u003d\u0033\u004a\u0060\u0032\u0044\u007d\u007e\u0065\u0077\u007a\u0073\u005a\u0023\u0042\u007d\u003a\u0058\u006d\u0070\u0047\u002b\u007c\u0060\u0062\u0069\u0031\u0041\u0028\u0066\u006c\u0079\u0034\u005d\u0025\u0041\u0070\u0077\u0067\u0044\u0058\u004f\u0078\u0025\u0029\u006d\u003b\u0049\u0065\u0066\u007c\u005e\u0041\u0033\u002a\u0070\u0077\u004a\u004d\u002a\u0035\u007e\u006a\u0070\u007d\u0078\u005b\u0053\u0022\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u002c\u0041\u0052\u0066\u0038\u0075\u0063\u0031\u0068\u0049\u0079\u0067\u007d\u007e\u0060\u005e\u0066\u0069\u0064\u0032\u0040\u0031\u003c\u0071\u0030\u004f\u006e\u0025\u0051\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u007e\u0071\u0078\u002b\u0075\u007e\u0073\u0077\u0022\u0074\u0077\u004a\u0053\u0058\u0064\u006d\u0061\u0078\u006c\u0078\u0053\u0039\u006d\u0055\u0051\u002a\u003b\u0050\u0070\u003d\u0030\u0029\u0058\u004f\u0028\u0078\u006a\u0042\u007d\u0055\u0022\u0074\u006d\u005b\u0021\u006e\u0042\u006a\u004f\u0071\u0079\u0067\u005e\u0022\u0054\u0061\u0069\u0035\u0031\u0029\u007c\u002a\u0030\u0029\u0058\u004f\u004e\u0047\u0066\u0075\u0067\u0067\u0068\u004a\u007d\u004a\u005f\u0035\u007c\u006f\u002a\u004c\u0061\u004f\u0057\u0075\u0023\u0045\u003a\u0041\u0030\u003c\u005e\u005a\u004c\u006d\u006d\u0070\u0068\u0033\u0077\u006b\u004c\u0077\u002f\u003c\u0047\u005a\u0079\u0022\u005d\u0062\u004f\u0071\u0059\u0066\u0074\u0033\u0058\u0033\u0067\u004b\u0079\u0050\u003c\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u004f\u006a\u007d\u0071\u003a\u002b\u0040\u0022\u0067\u0067\u004d\u0073\u0054\u005a\u0054\u0060\u004b\u0065\u002a\u004c\u0061\u004f\u0057\u0075\u0023\u0045\u003a\u0041\u0030\u003c\u005e\u005a\u0031\u0054\u003b\u0049\u0062\u0078\u0071\u005e\u0041\u0033\u003b\u0073\u006e\u0046\u006b\u0063\u0030\u0065\u0022\u0063\u003a\u002b\u0050\u0042\u0061\u0045\u006a\u003f\u0055\u0074\u0070\u003d\u0030\u0029\u0058\u004f\u0031\u0042\u0048\u0064\u0034\u0067\u0023\u007e\u0021\u005a\u0039\u005a\u0041\u006d\u007c\u0071\u0079\u0067\u007d\u007e\u005e\u0072\u0057\u0041\u0024\u0032\u0024\u005a\u002b\u0031\u0039\u002e\u0078\u002b\u002f\u007c\u0041\u0033\u003a\u0041\u0030\u003c\u003f\u0043\u0068\u0034\u0073\u0070\u0059\u0066\u006c\u0053\u005b\u0075\u006a\u003f\u0055\u0074\u0070\u003d\u0030\u0029\u0058\u004f\u0031\u0042\u0048\u0064\u0034\u0067\u0023\u007e\u007e\u0032\u005e\u0031\u0041\u006d\u0074\u0049\u0062\u0078\u0053\u0039\u006d\u0055\u0064\u007b\u005f\u0035\u0079\u006e\u0037\u0033\u0079\u0049\u003e\u0066\u006a\u0042\u0075\u003a\u002c\u0041\u0055\u0032\u0024\u005a\u0046\u0058\u004d\u0052\u006f\u0059\u007c\u0033\u006f\u0077\u006b\u003c\u0057\u005a\u004e\u0031\u006c\u0059\u0048\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u004e\u0047\u0066\u0075\u0067\u0067\u007a\u0025\u0058\u0053\u005b\u0075\u0056\u003c\u003c\u0059\u0061\u002a\u0035\u007e\u003c\u0070\u0054\u002f\u007d\u0053\u0041\u0033\u003b\u0073\u0034\u0068\u0061\u0074\u0078\u006d\u007c\u0071\u0035\u0030\u003b\u0068\u005d\u0067\u0042\u0074\u006a\u0059\u0036\u0046\u006c\u002b\u0064\u0049\u0069\u0050\u0068\u0036\u0063\u0036\u003b\u0073\u0057\u005a\u005d\u002b\u002f\u0039\u003a\u0043\u0078\u0025\u0030\u0029\u0072\u0078\u0061\u0049\u0063\u0028\u007d\u0055\u0024\u0068\u0030\u003c\u0072\u002c\u004f\u0023\u006d\u0070\u004d\u0049\u0063\u0028\u0025\u0052\u0064\u0035\u0036\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0076\u0070\u0044\u004a\u0057\u003a\u0067\u003a\u0038\u005a\u0037\u0044\u003a\u007d\u0060\u005e\u0054\u0069\u0053\u0064\u002e\u0035\u0076\u0070\u0028\u003c\u004a\u005a\u005d\u0043\u0050\u005a\u004c\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0044\u0065\u0038\u0076\u006b\u0078\u0073\u0058\u003e\u005e\u0064\u0035\u006d\u0042\u0070\u0048\u0032\u005d\u0022\u0053\u002c\u0025\u002c\u004e\u0038\u0076\u005e\u0078\u0049\u0058\u003e\u005e\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0042\u0032\u0074\u0069\u0076\u002f\u0029\u0051\u002f\u0038\u0057\u004f\u004d\u0050\u005d\u0043\u0042\u005e\u0041\u0036\u0036\u0029\u004a\u002a\u0030\u0029\u0069\u0053\u0033\u0057\u005d\u0044\u0058\u004f\u0078\u0025\u0069\u0054\u0077\u0071\u0053\u002b\u0033\u0077\u0054\u0075\u0068\u004a\u0040\u006e\u0033\u0038\u005f\u006a\u0043\u0030\u0064\u0049\u003b\u0068\u0049\u0057\u0023\u007b\u004f\u004a\u0073\u0050\u0036\u0029\u0058\u0047\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u006a\u0070\u0072\u0050\u0075\u007e\u0026\u004b\u003c\u0067\u004e\u0066\u005b\u002a\u0034\u0034\u003b\u0049\u005e\u0076\u007c\u0061\u0048\u0055\u003e\u002e\u0032\u0023\u006b\u004d\u0075\u0065\u0066\u0078\u0038\u002b\u003b\u0068\u006d\u0075\u0076\u0068\u0054\u0023\u0026\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0072\u0078\u0061\u0049\u0063\u0028\u007d\u0055\u002b\u0060\u0048\u0060\u0056\u0035\u0046\u0054\u0078\u004f\u006e\u0025\u0034\u0034\u003b\u0049\u005e\u0076\u007c\u0061\u0031\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0041\u0039\u007e\u0031\u005a\u002a\u0073\u0035\u007e\u0062\u0043\u0023\u0059\u0053\u005b\u0045\u0075\u0062\u007d\u004e\u0021\u004f\u0064\u0032\u0072\u0022\u0076\u0071\u004c\u0078\u007e\u0029\u005d\u0058\u007c\u0047\u0021\u004f\u0064\u0032\u0072\u0022\u0076\u0071\u0068\u0078\u007e\u0029\u0040\u003a\u0061\u0055\u0023\u007b\u004f\u004a\u0073\u0050\u0073\u0076\u0077\u0053\u0079\u0067\u005d\u0058\u006d\u0055\u0023\u007b\u004f\u004a\u0073\u0050\u0022\u0030\u0077\u0053\u0047\u0025\u006a\u0058\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006b\u0076\u0026\u0053\u002a\u005d\u0071\u007e\u0073\u0035\u007e\u0062\u0043\u0023\u0059\u0053\u005b\u0045\u0066\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0075\u0048\u0077\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u006d\u002b\u0035\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006a\u0024\u006d\u0070\u0053\u0054\u007c\u0061\u0048\u0055\u0023\u0041\u007c\u003c\u0068\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0044\u0057\u003a\u0043\u0078\u0025\u0030\u0029\u006a\u0070\u006d\u0049\u0026\u0042\u0076\u0036\u003c\u0067\u0032\u0023\u0057\u0031\u0035\u0067\u0024\u0078\u002c\u0059\u006e\u0057\u0039\u0077\u0070\u0062\u0073\u0035\u007e\u0062\u0043\u0023\u0023\u003d\u0057\u0077\u006a\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0025\u0023\u006a\u0042\u0061\u0045\u0039\u0067\u006e\u006f\u005b\u007a\u0033\u004e\u006b\u0070\u0074\u003d\u006a\u0053\u003f\u005d\u006d\u0062\u0049\u0035\u0049\u0035\u004b\u0065\u002a\u004c\u0032\u0025\u0046\u0054\u0028\u0071\u004a\u0029\u0071\u0039\u007c\u0047\u0047\u0051\u004d\u0066\u005f\u0035\u0074\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0044\u005f\u0055\u0057\u0036\u007e\u0064\u0055\u0052\u0078\u004d\u0066\u0077\u0038\u0040\u0034\u0034\u0056\u003c\u0029\u0074\u005e\u0072\u0067\u004a\u0070\u0063\u0035\u0052\u0035\u0033\u004e\u0028\u0071\u0035\u0030\u0031\u0064\u0053\u0033\u0038\u0062\u0073\u0035\u007e\u0062\u0043\u0023\u0023\u003d\u0057\u0077\u006a\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0025\u0023\u006a\u0042\u0061\u0045\u0039\u0067\u006e\u006f\u005b\u007a\u0033\u004e\u006b\u0070\u0060\u0030\u0050\u0042\u0049\u0057\u004b\u004a\u007d\u004a\u005f\u0035\u007b\u0029\u0037\u002e\u0047\u0025\u003e\u0022\u0041\u004f\u003d\u0076\u003a\u002f\u0048\u0055\u005f\u0036\u004b\u0028\u005d\u0032\u0076\u0023\u004f\u0071\u0050\u0021\u0041\u0039\u0031\u0055\u0039\u0029\u0078\u0032\u003a\u0035\u0029\u0034\u004c\u0034\u0049\u004e\u003a\u002f\u0053\u0033\u0062\u0062\u005f\u003e\u006c\u0079\u007a\u007e\u0037\u002e\u0076\u0043\u005d\u0058\u006d\u0055\u0023\u0041\u007c\u003c\u0073\u004d\u002f\u0039\u0073\u004f\u0078\u0025\u006d\u002b\u0035\u0043\u0059\u0025\u0030\u0029\u0058\u004f\u005a\u0052\u0041\u0039\u0055\u0033\u0031\u007b\u003a\u003e\u0042\u0062\u0040\u0034\u0034\u0056\u003c\u0029\u002f\u0053\u0043\u0051\u003c\u0024\u0064\u003c\u006e\u0026\u004e\u006d\u002b\u003f\u002a\u0049\u004c\u0028\u0051\u005b\u0061\u0029\u0021\u004a\u006d\u0074\u0021\u004e\u0035\u0070\u0023\u0052\u0032\u002f\u0048\u002a\u0061\u0029\u0049\u0035\u0071\u0035\u002b\u0054\u0059\u0071\u0041\u002b\u0033\u0077\u0054\u0075\u0031\u004d\u002b\u006f\u004a\u002a\u0076\u0070\u0076\u0056\u0054\u0064\u004c\u0028\u0069\u0077\u0040\u007d\u0068\u003c\u006c\u0079\u003b\u0069\u0054\u0070\u0057\u0029\u004e\u006b\u0043\u0051\u0062\u0050\u002e\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u003e\u0054\u0066\u0075\u0075\u0067\u0032\u007b\u0030\u003c\u0043\u0061\u0052\u0038\u0040\u0024\u0043\u0065\u006f\u0028\u005b\u004d\u0034\u0042\u0047\u005a\u0036\u0046\u0046\u0054\u0055\u0049\u006b\u0076\u0032\u002f\u0026\u002c\u007c\u0042\u0028\u0066\u0066\u004d\u0076\u0070\u0035\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006a\u0024\u006d\u0070\u0053\u0054\u007c\u0061\u0048\u0055\u0057\u0041\u004f\u0066\u006d\u0074\u0072\u0038\u0040\u0024\u0043\u0065\u006f\u0028\u002b\u0053\u007e\u0042\u004b\u003c\u003f\u0038\u0035\u002b\u005d\u004c\u0031\u0042\u0075\u007e\u0023\u0021\u0042\u0049\u007b\u0074\u005d\u002b\u003a\u0073\u0034\u0056\u0038\u0049\u007c\u0033\u003a\u0058\u0031\u0035\u0031\u0029\u004a\u002a\u0030\u0029\u0044\u005f\u0055\u0057\u0036\u007e\u0064\u0055\u0052\u0078\u004d\u0066\u0077\u0038\u0040\u0034\u0034\u0056\u003c\u0029\u002f\u0053\u005b\u0075\u003f\u007d\u004f\u004a\u003b\u0046\u0046\u0054\u0055\u0049\u006b\u0076\u0032\u002f\u0026\u002c\u007c\u0042\u0028\u0066\u0049\u0035\u0071\u002c\u005b\u0070\u002a\u002b\u0034\u002f\u002b\u0055\u004a\u003c\u002b\u004d\u0058\u0051\u0067\u0054\u007c\u0030\u0054\u004e\u0066\u0075\u0028\u006b\u0064\u0035\u0077\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0076\u0070\u0076\u0056\u0054\u0064\u004c\u0028\u0037\u005d\u0034\u0042\u0047\u005a\u007e\u0034\u0032\u0076\u0071\u004f\u006e\u0025\u0031\u0054\u003b\u0049\u003b\u0052\u0074\u0068\u004d\u0022\u0041\u0073\u0059\u004a\u0035\u0074\u003a\u0070\u0039\u003f\u0067\u0050\u003b\u0068\u005d\u0067\u0075\u0079\u004f\u004a\u0073\u0050\u0036\u0029\u0076\u0076\u0072\u0055\u004b\u0077\u0052\u0064\u0063\u0062\u0023\u006e\u0073\u004d\u002b\u0034\u007d\u0071\u0059\u0029\u0023\u006f\u0062\u0058\u0052\u0049\u005b\u006f\u0041\u002a\u005a\u0029\u0033\u0063\u0030\u0077\u0067\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006d\u0039\u0044\u002f\u0066\u0057\u003a\u0041\u0055\u0032\u0057\u005a\u007d\u0076\u0074\u0049\u0067\u0068\u0026\u0053\u0075\u0067\u0028\u0032\u0036\u0035\u0041\u004d\u0048\u0029\u0059\u0049\u0078\u002b\u0041\u0061\u006d\u0075\u0075\u0048\u0077\u0035\u0032\u007a\u0048\u005d\u005b\u0070\u0033\u0024\u004f\u0028\u0038\u0069\u0035\u0041\u0073\u004d\u007a\u005d\u0074\u0070\u0064\u0043\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0072\u0078\u0061\u0049\u0063\u0028\u007d\u0055\u0024\u0068\u0030\u003c\u005b\u0074\u007e\u006f\u002a\u004c\u0031\u0042\u0035\u005e\u0045\u004b\u0026\u003f\u0062\u003e\u0057\u005a\u0021\u004e\u0066\u003d\u0076\u0054\u007c\u0061\u005e\u0033\u003b\u0073\u006e\u0046\u007e\u0062\u0043\u0023\u0023\u003d\u0033\u0057\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u007c\u002e\u006e\u006f\u0068\u0075\u0063\u0031\u007d\u0071\u0069\u0050\u0053\u0039\u007c\u0047\u005e\u0029\u0042\u0035\u0058\u0058\u0064\u006d\u0061\u0078\u006c\u0078\u004d\u0043\u0073\u005d\u007a\u0073\u005b\u0066\u0041\u005a\u006d\u0059\u007b\u0034\u003b\u002e\u007d\u007e\u0057\u0033\u0037\u0073\u0078\u006e\u0070\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0043\u003e\u0075\u007e\u0048\u006a\u0060\u0067\u0071\u0032\u005d\u0022\u0035\u002b\u003a\u004c\u006e\u0025\u0079\u0038\u0024\u0078\u002e\u0076\u0074\u0075\u006b\u0079\u005b\u0063\u0068\u003c\u0073\u004d\u006a\u0024\u006d\u0070\u0053\u0054\u007c\u0061\u0048\u0055\u0041\u0041\u004b\u003c\u0045\u0046\u0035\u002b\u0057\u004f\u0023\u002a\u003c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0024\u0064\u0033\u0055\u0062\u0050\u004e\u0066\u0047\u007a\u0033\u004e\u006b\u0070\u0075\u005b\u003a\u002f\u0056\u0057\u0057\u0041\u004f\u0066\u006d\u0074\u0072\u0038\u0040\u0024\u0043\u0065\u006f\u0028\u0028\u006b\u0045\u0044\u0038\u0053\u0072\u0067\u007d\u0063\u0071\u003c\u006e\u0026\u002f\u0039\u003a\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0076\u0070\u0076\u0056\u0054\u0064\u004c\u0028\u0069\u0077\u003e\u002e\u0075\u0035\u004d\u002a\u0035\u007e\u0073\u002e\u0078\u002b\u004b\u0023\u0038\u0069\u007d\u004b\u004f\u004a\u0056\u0035\u005a\u0054\u0059\u0056\u0040\u0076\u0063\u0028\u0026\u004b\u007d\u0063\u0059\u005a\u0024\u005a\u0046\u0058\u004f\u0056\u0032\u0050\u0041\u005e\u0061\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0079\u0048\u0055\u007e\u007c\u0074\u0057\u0031\u005b\u003d\u0041\u0052\u007a\u0030\u0039\u0064\u0034\u0036\u0048\u003f\u0039\u0060\u0076\u006a\u003f\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0024\u0076\u004c\u0028\u0029\u004b\u002f\u003c\u0047\u0066\u006c\u0079\u006d\u002b\u007a\u0039\u0042\u003e\u0039\u0064\u0063\u0036\u004a\u0068\u003f\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u003b\u0069\u0076\u0056\u0024\u0029\u0065\u0033\u0041\u0072\u0058\u003c\u0047\u0066\u0047\u006e\u0030\u0031\u006d\u0070\u0023\u0052\u0044\u002f\u0069\u0077\u003e\u002e\u0075\u0035\u0058\u004d\u0076\u0070\u0035\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0031\u0042\u0041\u0061\u005f\u005d\u0025\u005d\u0052\u0066\u0047\u007a\u0033\u004e\u006b\u0070\u0074\u0030\u0048\u0064\u0053\u0033\u0065\u007e\u0069\u0028\u0064\u002c\u0070\u0071\u0054\u0052\u007d\u007c\u0031\u002f\u0031\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u004c\u0077\u0054\u0075\u0043\u0039\u005a\u0023\u0072\u0038\u002e\u0058\u006d\u0070\u0079\u0067\u0041\u0039\u0063\u0036\u006f\u0068\u0055\u0032\u0058\u0051\u003a\u0070\u0039\u003f\u0067\u0050\u003b\u0068\u005d\u0067\u0075\u0079\u004f\u004a\u0073\u0050\u007b\u0029\u003c\u0070\u004f\u002c\u004c\u0028\u0031\u0055\u007b\u0044\u006b\u0065\u002b\u0055\u0051\u0060\u007c\u0032\u006d\u0074\u0074\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0031\u0042\u0041\u0061\u005f\u005d\u0025\u005d\u0052\u0066\u0047\u007a\u0033\u004e\u006b\u0070\u0074\u0030\u0048\u0064\u0053\u0033\u0065\u007e\u0069\u0028\u005d\u0032\u0076\u0023\u004f\u0071\u0033\u0057\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0077\u0062\u0058\u0033\u0043\u0039\u005a\u0023\u005e\u002a\u004d\u003d\u003b\u0049\u003a\u0049\u002f\u0053\u0054\u003b\u0059\u0059\u0077\u0035\u0022\u0048\u007b\u0029\u005f\u0049\u004e\u0047\u0050\u0053\u0028\u006b\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0079\u0067\u006a\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0073\u0076\u0059\u0075\u005b\u0053\u0054\u0041\u0052\u0066\u0021\u0033\u0040\u0034\u003b\u0049\u006f\u0053\u0030\u005e\u0039\u005e\u0021\u004f\u0077\u0035\u0022\u0048\u0074\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0039\u006d\u003b\u0049\u003b\u0050\u0032\u002f\u0029\u004b\u002f\u003c\u005f\u005a\u0070\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0029\u0067\u0042\u0034\u0067\u0066\u007e\u005b\u004c\u007c\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0071\u002c\u0054\u0070\u0039\u0029\u0059\u005e\u003d\u0067\u0023\u007e\u0069\u0028\u0077\u0059\u0040\u0031\u006f\u0030\u003a\u004e\u0026\u0053\u007d\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0077\u0062\u005e\u0072\u002c\u007e\u007c\u0074\u005b\u007a\u0061\u0071\u007b\u0049\u003b\u002e\u0048\u0064\u0053\u0033\u002f\u0079\u0044\u003e\u0047\u006e\u0030\u0031\u006d\u0070\u0068\u004e\u005e\u0022\u0040\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0068\u004a\u004d\u0066\u0021\u0022\u0037\u0033\u0079\u0049\u003b\u0052\u0074\u0068\u004d\u0022\u0063\u007d\u0068\u003c\u006e\u0074\u002f\u0065\u002a\u004c\u0040\u002a\u0043\u0053\u0040\u0079\u0047\u0063\u0035\u005b\u0021\u006e\u0042\u006a\u004f\u0071\u0033\u0057\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u005e\u0022\u0041\u0072\u0058\u003c\u0047\u0066\u006a\u0033\u0059\u006a\u004c\u0049\u0028\u0029\u0078\u006f\u0069\u0077\u0060\u0067\u0038\u006e\u0029\u0062\u004e\u006f\u0051\u0078\u003b\u0050\u0050\u0053\u004d\u0075\u0048\u0063\u0074\u0032\u0072\u0022\u0071\u0038\u0057\u004f\u0076\u0076\u005d\u002f\u0052\u0048\u0064\u0035\u0054\u0023\u003d\u0035\u0071\u002c\u0055\u0049\u0053\u0076\u003d\u0033\u004a\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0068\u004a\u004d\u0066\u0021\u0022\u0037\u0033\u0079\u0049\u003b\u0052\u0074\u0068\u004d\u0022\u0063\u007d\u0068\u003c\u006e\u0074\u002f\u0065\u002a\u004c\u0026\u0056\u006b\u0028\u0024\u0077\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0063\u0076\u0063\u0028\u007d\u0055\u005e\u0029\u0074\u004d\u006d\u0048\u002f\u0031\u0070\u0071\u0038\u0049\u0050\u003a\u0058\u0033\u0043\u0039\u0036\u0060\u006a\u0033\u0059\u006a\u004c\u0049\u0056\u004e\u003c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0075\u0048\u0077\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006f\u006d\u0052\u0071\u0061\u0049\u002b\u0053\u0072\u0067\u004b\u004a\u005f\u005a\u006d\u0048\u003c\u0071\u0046\u0070\u0042\u0070\u0077\u0062\u0058\u0033\u0043\u0039\u0058\u0074\u0070\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0059\u0049\u0078\u002b\u0041\u0061\u006d\u0075\u0021\u004f\u0077\u0035\u0022\u0048\u0028\u0039\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0044\u0057\u0073\u004f\u0078\u0025\u006d\u002b\u0035\u0043\u0059\u0025\u0030\u0029\u0058\u004f\u003e\u0054\u0066\u0075\u0075\u0067\u0032\u007b\u0030\u003c\u0064\u002c\u0067\u0054\u0059\u0056\u0040\u0076\u006f\u004e\u0046\u0055\u0037\u004d\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u004f\u006a\u007d\u0071\u003a\u002b\u0053\u0039\u0040\u0072\u007a\u0041\u004e\u0066\u006c\u0079\u0034\u005d\u005b\u0070\u0042\u0065\u0045\u0053\u0028\u0036\u0044\u0042\u0058\u004a\u004d\u0074\u0076\u0045\u004d\u003f\u0050\u0064\u0050\u003a\u0041\u0072\u0070\u0063\u006d\u0035\u003c\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u006d\u0039\u0044\u002f\u0066\u0057\u0031\u007b\u007d\u005a\u004e\u0031\u0065\u0062\u0054\u0070\u0045\u0066\u004c\u0028\u0031\u0055\u005f\u0036\u004b\u0028\u006e\u0026\u0048\u0029\u0059\u0049\u0078\u002b\u0041\u0061\u006d\u0075\u0050\u002b\u004b\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0071\u002c\u0054\u0070\u0039\u0029\u0059\u005e\u003d\u0067\u0056\u003c\u0047\u0035\u0079\u0022\u003f\u0065\u002a\u004c\u003b\u002e\u0049\u0050\u0043\u0031\u0060\u0067\u003a\u003e\u0036\u005d\u0028\u0039\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0029\u006d\u003b\u0049\u006c\u006f\u0056\u0077\u0067\u0067\u0042\u007b\u007d\u005a\u0050\u002a\u0035\u007e\u0078\u0071\u0028\u006e\u0056\u0077\u0057\u0032\u003e\u0036\u0056\u0028\u004f\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u005a\u0052\u005e\u0022\u0040\u0048\u0041\u002e\u0044\u003e\u004d\u0074\u0035\u002b\u0034\u0056\u0040\u0076\u0063\u0028\u006d\u0067\u0049\u007e\u0060\u004a\u004a\u0050\u0034\u0070\u004a\u0056\u0073\u0076\u0072\u0062\u003a\u0069\u003b\u0073\u0064\u0032\u0058\u005a\u003c\u0071\u0064\u0049\u004c\u004a\u0048\u0064\u0036\u0055\u0075\u0060\u0054\u005a\u0071\u0035\u0034\u0070\u0037\u0078\u0072\u0050\u0056\u0077\u005e\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0041\u0039\u0040\u0072\u007a\u0041\u004e\u0066\u0025\u0033\u002e\u0058\u007b\u0049\u007b\u0055\u0046\u0043\u0025\u0052\u0040\u0029\u0074\u004d\u006d\u0048\u002f\u0031\u0063\u0049\u003f\u0049\u005e\u0077\u0021\u0077\u0062\u0050\u0054\u0023\u0024\u002a\u002b\u004b\u006e\u003e\u0030\u0077\u0045\u002a\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0054\u0033\u002b\u0055\u0078\u005d\u004e\u0066\u006f\u0062\u0072\u0038\u0030\u004f\u007c\u0065\u0032\u002f\u005e\u0072\u002e\u007e\u007a\u0032\u0048\u0038\u005a\u0065\u006a\u0070\u0072\u0050\u0072\u0062\u004f\u0036\u0070\u003c\u0047\u0066\u0047\u006e\u0030\u0031\u006d\u0070\u0046\u0046\u0031\u002f\u0072\u0072\u004d\u0041\u007d\u005a\u0024\u005a\u0028\u006f\u006a\u0070\u006b\u0076\u003b\u0068\u0034\u0036\u0048\u003f\u007d\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u0029\u002e\u0072\u0055\u0028\u0075\u004e\u006a\u002f\u003c\u0076\u0042\u004d\u0074\u0046\u006a\u003b\u0049\u0063\u0029\u0037\u0058\u006d\u0055\u0051\u0050\u0054\u0023\u0026\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u004e\u0047\u0066\u0075\u0067\u0067\u0021\u004f\u0059\u004a\u0055\u0050\u003d\u006d\u0066\u0058\u0028\u006e\u006a\u0042\u0025\u0052\u0075\u0048\u0068\u003c\u006e\u0074\u007d\u0071\u003e\u0058\u0041\u002b\u004a\u0064\u0072\u0033\u0022\u007b\u0068\u003c\u0067\u0046\u004d\u003d\u003b\u0049\u003a\u0049\u0038\u0053\u002b\u0075\u0064\u007b\u004c\u003c\u0067\u002b\u006a\u0024\u0057\u004f\u002e\u0047\u006a\u0053\u003d\u0067\u003a\u0069\u007d\u004a\u0052\u0061\u0028\u006f\u0050\u003d\u006c\u0077\u0067\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006c\u006f\u0058\u0053\u0049\u005d\u0042\u0032\u0028\u005a\u004c\u005a\u0034\u006a\u0047\u0071\u0065\u0047\u006a\u0053\u0035\u005a\u0075\u0048\u006d\u0023\u003e\u004d\u006a\u003d\u002a\u0071\u0039\u0047\u0065\u0075\u004a\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0077\u0062\u005e\u0033\u003b\u0073\u007d\u004a\u0049\u0043\u0063\u0034\u0066\u0049\u0061\u0024\u0059\u0033\u004a\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u005e\u0022\u0030\u0048\u002f\u003c\u0067\u006e\u0048\u002c\u007c\u006d\u006b\u006b\u0042\u0065\u0026\u0053\u0030\u0057\u0031\u0035\u0031\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006a\u0024\u006d\u0070\u0053\u0054\u007c\u0061\u0031\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0044\u0037\u005f\u0046\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0024\u006a\u004c\u0049\u0072\u0055\u004c\u0077\u0054\u0075\u0043\u0039\u005a\u0023\u0032\u007a\u0052\u006d\u0070\u004f\u002f\u003e\u0053\u0039\u0040\u0072\u007a\u0041\u0058\u005a\u004c\u002a\u006a\u0058\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006c\u006f\u0058\u0053\u0049\u005d\u0042\u0032\u004c\u0032\u0050\u0077\u005a\u0054\u0078\u004f\u006e\u0025\u0062\u0076\u0041\u006b\u0045\u0030\u0076\u0077\u0024\u0077\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0031\u0042\u0048\u0064\u0034\u0067\u0023\u007e\u0024\u005a\u005b\u007a\u004e\u006d\u0070\u004f\u006e\u0025\u0065\u0034\u007d\u0071\u007a\u0030\u0050\u0042\u0052\u0057\u0023\u007b\u004f\u004a\u0073\u0050\u007b\u0029\u003b\u0034\u002c\u0025\u0026\u0076\u0028\u0071\u0041\u0076\u003d\u0033\u004a\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0063\u0077\u0062\u0069\u0029\u0039\u0060\u006d\u0032\u007a\u0052\u006d\u0077\u0053\u0079\u0067\u0077\u0062\u0068\u0045\u0067\u004b\u0049\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u0029\u002e\u0072\u0055\u004d\u0075\u0041\u0072\u004d\u0041\u006e\u006f\u0053\u002a\u0074\u0054\u0074\u0049\u007a\u0064\u0055\u0077\u0047\u005d\u0072\u0074\u0054\u0023\u0026\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006a\u0024\u005b\u0070\u003a\u002b\u0075\u0036\u0041\u0072\u004d\u0041\u0032\u0023\u005e\u002a\u0036\u0071\u0076\u0056\u006b\u0076\u004c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u004e\u0041\u004e\u0066\u003b\u003e\u0030\u0031\u006d\u0070\u0079\u0067\u0041\u0039\u0040\u0072\u007a\u0041\u0049\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006d\u002b\u0035\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006d\u002b\u0035\u0043\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u002c\u0078\u0043\u0065\u006f\u0028\u0039\u0032\u004e\u0041\u004e\u0066\u003b\u003e\u0030\u0031\u006d\u0070\u007e\u0029\u0078\u006f\u0057\u0069\u004a\u003c\u005e\u007a\u0071\u003a\u0045\u0038\u0067\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0059\u0049\u002a\u0049\u0041\u005e\u003f\u005d\u0075\u0079\u004f\u004a\u0073\u0050\u007e\u0063\u0048\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0072\u0078\u003c\u0076\u0024\u0077\u0066\u0023\u0039\u007d\u0077\u0035\u0064\u0048\u004e\u0038\u006d\u0070\u004b\u0039\u003c\u0023\u003a\u0055\u0032\u0044\u0041\u0039\u0078\u0060\u0066\u0044\u007d\u007e\u0064\u0055\u0078\u0041\u0056\u0032\u0035\u0048\u002e\u006a\u007d\u0071\u0072\u0055\u0074\u0068\u002b\u0022\u002c\u0041\u0059\u003d\u0029\u0062\u0064\u006d\u0066\u0049\u0065\u0047\u006a\u0053\u0030\u0057\u0060\u0067\u0054\u0035\u006b\u0051\u0036\u0029\u0058\u0047\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0037\u002e\u004f\u0029\u0065\u0033\u002a\u0069\u003a\u0041\u0021\u0063\u006e\u0074\u0039\u0034\u0057\u004f\u006b\u0076\u0026\u0053\u002a\u005d\u0057\u0032\u0031\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u0029\u002e\u0072\u0055\u0063\u0077\u0062\u0069\u0029\u0039\u0060\u006d\u0039\u005a\u006d\u0054\u0041\u0052\u007e\u0029\u0071\u0039\u007c\u0047\u0047\u0051\u004d\u0066\u005f\u0035\u0036\u0029\u0059\u0049\u0078\u002b\u0041\u0061\u006d\u0075\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0059\u0031\u0070\u004f\u005d\u0042\u0041\u0061\u005f\u005d\u0025\u005d\u0052\u0066\u0041\u0035\u003a\u0076\u0035\u0070\u0024\u0029\u0071\u0039\u007c\u0047\u007a\u0025\u0043\u0053\u0040\u0079\u0047\u0063\u0035\u005b\u0021\u006e\u0042\u006a\u004f\u0071\u0047\u0025\u0039\u006d\u003b\u0049\u003b\u0050\u0066\u0075\u004a\u0060\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0029\u004b\u007c\u0042\u0028\u0066\u003a\u0071\u0063\u0031\u0057\u0070\u002b\u0069\u003c\u0042\u0025\u0052\u007a\u0025\u0043\u0053\u0040\u0079\u0047\u0063\u0035\u005b\u0021\u006e\u0042\u006a\u004f\u0071\u0033\u0057\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u004d\u0041\u0030\u003c\u0064\u0074\u003a\u0058\u004f\u0056\u0032\u0050\u007d\u0042\u007b\u0057\u0050\u002b\u004b\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u0029\u002e\u0072\u0055\u005a\u0042\u006b\u0033\u007c\u0032\u0050\u002b\u007d\u006e\u003c\u0071\u0045\u0049\u0041\u002b\u006a\u0042\u007b\u0057\u0045\u0044\u0038\u0053\u0072\u0067\u007d\u0063\u0056\u0032\u0070\u003d\u0049\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0031\u0042\u0041\u0061\u005f\u005d\u0025\u005d\u0052\u0066\u0041\u0035\u003a\u0076\u0035\u0070\u0024\u0029\u0078\u006f\u0057\u0069\u004a\u003c\u005e\u007a\u0071\u003a\u0045\u0038\u0067\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u005f\u0049\u0042\u0065\u0026\u0053\u003e\u0067\u0043\u004b\u003d\u0042\u0035\u0074\u0058\u0023\u005a\u0024\u0061\u0049\u0026\u0053\u004d\u0075\u0023\u007e\u0069\u0028\u0043\u0061\u006b\u006c\u005d\u002b\u005b\u0029\u004c\u0057\u0032\u0055\u004a\u003c\u0032\u006f\u0045\u0046\u0063\u0031\u0022\u0030\u0038\u0049\u002f\u0064\u0047\u0053\u002e\u0049\u002e\u0028\u007c\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u005f\u0049\u0042\u0065\u0026\u0053\u003e\u0067\u0043\u004b\u0076\u0068\u0056\u0035\u0043\u0071\u0064\u0049\u006d\u0043\u004f\u0053\u0033\u0055\u005e\u0029\u0067\u0050\u0022\u0048\u004e\u0038\u0058\u003f\u0021\u0066\u003c\u0023\u006f\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u005e\u0022\u005e\u0033\u006f\u0039\u003a\u006e\u004d\u0074\u003d\u006d\u007b\u0049\u007b\u0055\u0046\u0043\u0025\u0052\u0040\u0029\u005b\u004c\u007c\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u006f\u0030\u0065\u0047\u006a\u0053\u0030\u0057\u0031\u0035\u0031\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0046\u0054\u0055\u0049\u006b\u0076\u0032\u002f\u0068\u0046\u0044\u0042\u0053\u007a\u005d\u0022\u0035\u002b\u0041\u004f\u0025\u0078\u007c\u005e\u0040\u0033\u0070\u003c\u005e\u007a\u0071\u003a\u0045\u0038\u0067\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u0029\u002e\u0072\u0055\u0056\u0022\u002a\u0069\u003a\u0041\u0021\u0063\u006e\u0074\u0039\u0034\u0057\u004f\u005f\u006b\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u005e\u0022\u0067\u0067\u004d\u0073\u0054\u005a\u0054\u0060\u0039\u0031\u0075\u0049\u002b\u0069\u0069\u0075\u0055\u0072\u003b\u0073\u0077\u004a\u0069\u0048\u0035\u002b\u0041\u004f\u004b\u0022\u004e\u0053\u002a\u005d\u003c\u0024\u005b\u0066\u0041\u005a\u0071\u0029\u0044\u005e\u0063\u0066\u003c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0043\u0039\u0059\u004a\u004a\u007d\u0041\u006d\u007c\u0071\u007b\u0042\u0043\u0053\u0063\u0067\u0058\u0067\u0028\u0035\u004d\u0074\u0035\u002b\u0041\u004f\u005d\u0068\u0026\u0053\u0075\u0067\u003f\u003c\u007b\u0050\u0070\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0044\u005f\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006a\u0024\u006d\u0070\u0052\u0059\u003b\u0068\u007a\u002c\u007c\u0042\u0028\u0066\u0036\u0046\u0050\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006d\u002b\u004d\u0076\u0025\u0023\u006d\u0065\u0037\u0057\u0050\u002b\u002b\u006f\u004a\u002a\u006d\u002b\u0035\u0043\u0059\u0025\u0030\u0029\u0058\u004f\u003e\u0054\u0066\u0075\u0075\u0067\u0032\u007b\u0030\u003c\u0030\u0038\u0075\u0054\u007b\u0078\u0051\u0066\u006f\u005e\u0041\u0033\u0041\u0073\u0059\u004a\u0035\u0074\u007e\u0063\u0057\u004f\u005f\u006b\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0074\u007b\u0071\u0032\u0022\u0048\u004a\u005d\u0060\u0030\u0064\u0049\u003b\u0068\u0036\u0055\u005e\u0029\u0056\u004a\u0046\u0074\u004f\u0071\u0026\u0041\u0038\u0049\u003c\u0053\u003f\u005d\u0059\u0059\u0064\u0032\u0072\u0022\u0054\u0076\u0048\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0037\u002e\u004f\u0029\u0065\u0033\u0076\u0036\u004a\u0067\u007d\u004a\u0058\u004d\u0076\u0070\u0035\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0033\u0076\u0052\u0071\u0057\u0047\u0045\u0053\u003f\u005d\u0075\u0048\u0054\u006f\u0037\u0022\u0071\u006d\u005d\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u0029\u002e\u0072\u0055\u006c\u0053\u005b\u0075\u0023\u0041\u0028\u0066\u006c\u0079\u007b\u004d\u0041\u004f\u0025\u0078\u007c\u005e\u0040\u0033\u0070\u003c\u005e\u007a\u0071\u003a\u0045\u0038\u0050\u003d\u0057\u0077\u006a\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0067\u003f\u0038\u0049\u0054\u0075\u0053\u0041\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u002b\u004e\u0066\u0075\u0077\u003a\u0063\u0067\u0056\u005a\u006b\u0051\u0051\u0071\u004f\u0056\u0047\u002b\u003b\u0068\u005d\u0067\u0075\u0048\u006d\u0023\u006b\u004d\u0061\u0071\u0045\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u007c\u0023\u0073\u0078\u0053\u0054\u005b\u0053\u0063\u0077\u0062\u0024\u0077\u004a\u0048\u0048\u007a\u0067\u007d\u0071\u005e\u0076\u0032\u002f\u007d\u0055\u005e\u0029\u005d\u007c\u003b\u005f\u0062\u004a\u0049\u004f\u0034\u0047\u006b\u0028\u0039\u006d\u003c\u0067\u006e\u006f\u0032\u0054\u0041\u007e\u0034\u0057\u0038\u004e\u0032\u002f\u003e\u0067\u003a\u007c\u0067\u0050\u0070\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0076\u0070\u007b\u0049\u0041\u002b\u0077\u0075\u0077\u003a\u0063\u0067\u0056\u004a\u0029\u0062\u007d\u0071\u0068\u0058\u004d\u0030\u006a\u0042\u0025\u0052\u0042\u0049\u0055\u0066\u006f\u0062\u0078\u006d\u0064\u0049\u006f\u005a\u0039\u0064\u007a\u0058\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0024\u0076\u004c\u0028\u005a\u004b\u007d\u0063\u0059\u005a\u0024\u005a\u0028\u006f\u0045\u0049\u0073\u0029\u0078\u006f\u0072\u0072\u0070\u0063\u0057\u005a\u003c\u0063\u0072\u0038\u0066\u003d\u0056\u0047\u0039\u0064\u005d\u0067\u0054\u0041\u0043\u003c\u002e\u0048\u003f\u0065\u0021\u0049\u0079\u0052\u0032\u002f\u0053\u0033\u003b\u0073\u004e\u0060\u0074\u003b\u0052\u006f\u003b\u0034\u0033\u0057\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0078\u0072\u0060\u0067\u0047\u005a\u0054\u0060\u0039\u0031\u0075\u0049\u002b\u0069\u0069\u0075\u0055\u0072\u003b\u0073\u0077\u004a\u0069\u0048\u0035\u002b\u0041\u004f\u0076\u0054\u007c\u0061\u005e\u0033\u003b\u0073\u0063\u003d\u0078\u0031\u0034\u0070\u0057\u004f\u0038\u0077\u0067\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0029\u0067\u0042\u0034\u0067\u0066\u007e\u005b\u004c\u007c\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0062\u006a\u0068\u0049\u0041\u0076\u0054\u0075\u0053\u0041\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0070\u0047\u0054\u0075\u005e\u0033\u0054\u0041\u0043\u003c\u002e\u0048\u003f\u0065\u0021\u0049\u0079\u0052\u0032\u002f\u0053\u0033\u003b\u0073\u005a\u0023\u005e\u002a\u0062\u006a\u0068\u0049\u0041\u0076\u0054\u0075\u004a\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0068\u004a\u005f\u005a\u006d\u0048\u006a\u0071\u0071\u0073\u0074\u0049\u005a\u0053\u006d\u003b\u0056\u003c\u0050\u003c\u0069\u0048\u0037\u0033\u0079\u0049\u0079\u0067\u005e\u0022\u0051\u0072\u004b\u003d\u0061\u0055\u0068\u0029\u0066\u0043\u004d\u0041\u0061\u0049\u003f\u0022\u0064\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u004f\u0028\u0038\u0069\u0035\u0041\u0057\u005a\u0073\u0035\u0031\u0070\u0028\u0071\u0062\u0064\u003d\u0061\u0056\u0069\u003a\u0041\u0032\u0023\u005e\u002a\u0047\u0070\u007b\u0049\u0041\u002b\u0077\u0075\u0036\u0055\u0022\u007b\u0058\u005a\u0030\u0061\u002f\u0039\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0079\u0067\u006a\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006b\u0076\u0032\u002f\u0057\u0033\u004b\u0063\u0074\u0032\u0072\u0022\u0030\u0065\u0047\u003d\u0033\u0057\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0073\u005d\u007a\u0073\u005b\u0066\u0041\u005a\u0056\u002c\u0055\u0049\u0053\u0076\u004c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0029\u0046\u006f\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0041\u0039\u007e\u0031\u005a\u002a\u002a\u006e\u0049\u0043\u0063\u0034\u0066\u0049\u006c\u004a\u0057\u0028\u0024\u0077\u0059\u0059\u0064\u0032\u0072\u0022\u0054\u0076\u0047\u003d\u0057\u0077\u006a\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u007b\u0043\u004f\u0053\u0077\u0061\u007a\u0041\u0028\u0066\u006c\u0079\u0071\u002c\u0055\u0049\u0053\u0076\u004c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0068\u004a\u005f\u005a\u006d\u0048\u006a\u0071\u0071\u0073\u0074\u0049\u005a\u0053\u006d\u003b\u0056\u003c\u0050\u003c\u0069\u0048\u0037\u0033\u0079\u0049\u0079\u0067\u005e\u0022\u0051\u0072\u0029\u004e\u005a\u0058\u0048\u006f\u0039\u0034\u006c\u003f\u006f\u0066\u003c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0068\u004a\u005f\u005a\u006d\u0048\u006a\u0071\u0071\u0073\u0074\u0049\u005a\u0042\u0062\u0069\u0030\u003c\u0048\u004d\u007d\u006e\u003f\u0065\u002a\u004c\u0065\u0066\u004f\u0028\u0038\u0069\u0035\u0041\u0058\u0066\u0036\u0023\u0039\u0034\u006c\u003f\u0070\u0077\u0067\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006b\u0076\u0032\u002f\u0057\u0033\u004b\u0063\u0074\u0032\u0072\u0022\u0030\u0065\u0047\u003d\u0033\u0057\u0036\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0073\u005d\u007a\u0073\u005b\u0066\u0041\u005a\u0056\u002c\u0055\u0049\u0053\u0076\u004c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0029\u0046\u006f\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0077\u0062\u005e\u0033\u0035\u0041\u004f\u0066\u0046\u002a\u0026\u0076\u0028\u0071\u0041\u0076\u004c\u0023\u003a\u0055\u0032\u0044\u0041\u0039\u0078\u0060\u0066\u0044\u007d\u007e\u0064\u0055\u0078\u0041\u0056\u0032\u0035\u0048\u002e\u006a\u007d\u0071\u0025\u0023\u003b\u0068\u002b\u0022\u0047\u0063\u006e\u0046\u007e\u0062\u0043\u0023\u003e\u003d\u0047\u0025\u006a\u0058\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0046\u0054\u0028\u0071\u004d\u0064\u0042\u0038\u005e\u0072\u004d\u0041\u0028\u0035\u0048\u0046\u0022\u0029\u0051\u0078\u0051\u0078\u003a\u002f\u002b\u0055\u007b\u0074\u0054\u0023\u0038\u0021\u0076\u0070\u0035\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u004f\u006a\u007d\u0071\u003a\u002b\u0072\u0062\u0038\u0069\u0078\u007e\u0069\u0028\u0044\u003a\u0063\u0034\u0066\u0049\u006f\u0075\u004b\u005e\u0069\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u005e\u0022\u0058\u0033\u0067\u004b\u003d\u0042\u0035\u0074\u0058\u0023\u005a\u0024\u0061\u0049\u0026\u0053\u004d\u0075\u0023\u007e\u0069\u0028\u0059\u0077\u004e\u0038\u002e\u004f\u0059\u005d\u0040\u0022\u003a\u0058\u0050\u002b\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0031\u0042\u006a\u0042\u0024\u0077\u0067\u004a\u007c\u0032\u0073\u0031\u0068\u0031\u003c\u0078\u0073\u0076\u0053\u0039\u006d\u0055\u0026\u004a\u007d\u004a\u005f\u0035\u005f\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0059\u0031\u0070\u004f\u0041\u0035\u0050\u0042\u0048\u0055\u005f\u0036\u004b\u0028\u0043\u0061\u004d\u0045\u0052\u003d\u0031\u0042\u006a\u0042\u0024\u0077\u0067\u004a\u007c\u0032\u0073\u0031\u0060\u0023\u007e\u0030\u003a\u002b\u0068\u004e\u0064\u0022\u003c\u0062\u005d\u007c\u0062\u0061\u0050\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0059\u0031\u0070\u004f\u0041\u0035\u0050\u0042\u0048\u0055\u005f\u0036\u004b\u0028\u0043\u0061\u0055\u0045\u0052\u003d\u0031\u0042\u006a\u0042\u0024\u0077\u0067\u004a\u007c\u0032\u0073\u0031\u0060\u0023\u007e\u0030\u003a\u002b\u0068\u004e\u0064\u0022\u003c\u0062\u0067\u0050\u0052\u0061\u0050\u0070\u0064\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0059\u0031\u0070\u004f\u0059\u0066\u007c\u005e\u0041\u0033\u002a\u0070\u0077\u004a\u004d\u002a\u0052\u0023\u0071\u004f\u0028\u0065\u003a\u002f\u0058\u0024\u005f\u0036\u0054\u006f\u003d\u007d\u0022\u0038\u0050\u003d\u0031\u0042\u006a\u0042\u0024\u0077\u0067\u004a\u007c\u0032\u0073\u0031\u0060\u0023\u007e\u0030\u003a\u002b\u0068\u004e\u0064\u0022\u003c\u0062\u005d\u007c\u0066\u004d\u006b\u0034\u0064\u0078\u0024\u0076\u005e\u0077\u0079\u0057\u0050\u002b\u004b\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u004f\u006a\u007d\u0071\u003a\u002b\u0040\u0022\u0076\u0036\u004a\u0067\u007d\u004a\u004d\u002a\u0035\u007e\u0072\u0078\u003c\u0076\u0024\u0077\u0047\u006d\u0060\u0067\u0071\u0032\u005d\u0022\u0039\u0073\u0076\u0056\u0032\u0050\u0041\u005e\u0061\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0041\u0039\u007e\u0031\u005a\u002a\u0021\u005a\u0039\u005a\u0028\u006d\u0066\u0049\u0047\u0025\u006a\u0058\u0073\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u006b\u0047\u006f\u0028\u0066\u0057\u0074\u007b\u0071\u0032\u0022\u0048\u0071\u0029\u0073\u0078\u0038\u002b\u003b\u0068\u006d\u0075\u002f\u0079\u0044\u003e\u0038\u0075\u0063\u0031\u0039\u0057\u0041\u002b\u0026\u0053\u003f\u005d\u0058\u003c\u004e\u0060\u0076\u006a\u003f\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0054\u0059\u0029\u002e\u0072\u0055\u0063\u0077\u0062\u0069\u0029\u0039\u007c\u0034\u0043\u0062\u004f\u0023\u006d\u0070\u004d\u0049\u0043\u0042\u0038\u005a\u0065\u007e\u004b\u0061\u0059\u007b\u0034\u005d\u0060\u0030\u0064\u0049\u003b\u0068\u0036\u0055\u0064\u0078\u005b\u006f\u005b\u007a\u0033\u004e\u006b\u0070\u0029\u002c\u0050\u0042\u0045\u0067\u0047\u0063\u0056\u0032\u0071\u004b\u0053\u0054\u0078\u004f\u0024\u0045\u0078\u006f\u0033\u006a\u0060\u0067\u0071\u0032\u005d\u0022\u0079\u0069\u0030\u0063\u006c\u006f\u0058\u0053\u0049\u005d\u0042\u0032\u004b\u0032\u006d\u0048\u0078\u006d\u0066\u0049\u0076\u0075\u003b\u004e\u0054\u005a\u0075\u0048\u0022\u0061\u005e\u002a\u005f\u0034\u007d\u0071\u0039\u0076\u0050\u0053\u0046\u0055\u0037\u004d\u002b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0073\u0078\u0038\u002b\u003b\u0068\u006d\u0075\u0022\u0078\u0068\u003c\u0054\u0060\u0043\u0071\u0032\u002e\u004b\u0039\u007d\u0042\u0077\u0055\u0028\u005d\u006d\u0023\u0026\u003d\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0043\u003e\u0075\u007e\u0021\u0048\u003c\u0062\u005a\u0023\u0059\u007b\u0035\u007e\u0037\u002e\u0047\u0025\u0046\u0054\u0028\u0071\u0074\u0049\u005a\u0042\u0062\u0069\u0030\u003c\u003f\u004d\u0057\u0031\u002b\u0031\u0076\u0078\u0053\u0059\u007c\u0033\u0031\u006a\u0060\u0067\u0079\u0050\u003c\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0069\u0034\u0048\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0079\u0067\u006a\u0044\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0044\u005f\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006d\u002b\u0035\u0043\u0078\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u006d\u002b\u0068\u003d\u0033\u0057\u0036\u007e\u0064\u0055\u0075\u0048\u0077\u0029\u007c\u002a\u0030\u0029\u0058\u004f\u003e\u0054\u0066\u0075\u0075\u0067\u0032\u007b\u0030\u003c\u005d\u0032\u0066\u006a\u004f\u0039\u004d\u0030\u006a\u0042\u007b\u0057\u0064\u0035\u0077\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u006a\u0024\u0076\u0056\u0032\u0050\u007d\u0042\u0025\u0052\u0041\u007c\u0042\u0066\u0065\u0062\u0041\u006f\u002f\u0066\u0077\u0056\u005f\u005e\u0055\u0077\u0070\u0062\u0078\u0032\u003a\u0035\u0029\u0034\u0048\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u0072\u0078\u003b\u0050\u0050\u0053\u004d\u0075\u0023\u007e\u006f\u0032\u0032\u005d\u0021\u004e\u0030\u004f\u006e\u0025\u0079\u0038\u0024\u0078\u002e\u0076\u0074\u0075\u006b\u0079\u005b\u0063\u0068\u003c\u0068\u006a\u0049\u0044\u005b\u006f\u004a\u002a\u0030\u0029\u0058\u004f\u0065\u0066\u007c\u005e\u0041\u0033\u002a\u0070\u0077\u004a\u004d\u002a\u0035\u007e\u006a\u0070\u007d\u0078\u005b\u0053\u0022\u003f\u0066\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u007d\u007e\u0069\u0077\u0040\u007d\u0068\u003c\u005f\u0038\u007e\u006d\u0055\u0078\u004b\u0024\u0059\u0033\u004a\u0060\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u005e\u0022\u0067\u0067\u004d\u0073\u0054\u005a\u0054\u0060\u0039\u0031\u0075\u0049\u002b\u0069\u0069\u0075\u0055\u0072\u003b\u0073\u0077\u004a\u0069\u0048\u0035\u002b\u0041\u004f\u004b\u0022\u004e\u0053\u002a\u005d\u003c\u0024\u005b\u0066\u0041\u005a\u0071\u0029\u0044\u005e\u0077\u0056\u005e\u0022\u0060\u0036\u0071\u007e\u0056\u005a\u0046\u002a\u0031\u0054\u003b\u0049\u0058\u005e\u006d\u0065\u0053\u0046\u0060\u0068\u0030\u003c\u0078\u0031\u004c\u005d\u0031\u0066\u0059\u0025\u0030\u0029\u0058\u004f\u0078\u0025\u0030\u0029\u005f\u0049\u0042\u0065\u0026\u0053\u003e\u0067\u0043\u004b\u0076\u0068\u0056\u0035\u0043\u0071\u0064\u0049\u006d\u0043\u004f\u0053\u0033\u0055\u005e\u0029\u0067\u0050\u0022\u0048\u004e\u0038\u0058\u003f\u0021\u0066\u003c\u0023\u003a\u0055\u0032\u0044\u007d\u007e\u0064\u0055\u0032\u0044\u0038\u0053\u004d\u0075\u0041\u0041\u0028\u0066\u0047\u007a\u0033\u004e\u006b\u0070\u004b\u0039\u003c\u0023\u003a\u0055\u0032\u0044\u0041\u0039\u0078\u0060\u0066\u0044\u007d\u007e\u0064\u0055\u0057\u0041\u006f\u003c\u0041\u0031\u0023\u004b\u0076\u0056\u006b\u0076\u007c\u0077\u0030\u0048\u0067\u002a\u0049\u0035\u0049\u0035\u0022\u0038\u0057\u004f\u0047\u004e\u0041\u0039\u0022\u0047\u0064\u0035\u0077\u0029\u004a\u002a\u0030\u0029\u0058\u004f\u0078\u0025\u0076\u0070\u005b\u0070\u007b\u0078\u0068\u004e\u0064\u0022\u0041\u0041\u0048\u005a\u0024\u005a\u004f\u0023\u007e\u0030\u003a\u002b\u003b\u0068\u0041\u0033\u0062\u0062\u0067\u0050\u0056\u0035\u0070\u0071\u004b\u0030\u004a\u0078\u007d\u007e\u007b\u0057\u0075\u0048\u0079\u0028\u0049\u0046\u0031\u0033\u0057\u0070\u0024\u0076\u007c\u0060\u0062\u0069\u0031\u0041\u004f\u005a\u003a\u007a\u0052\u006d\u003e\u003d\u0047\u004e\u0059\u0033\u004a\u0060\u0032\u0044\u007d\u007e\u0044\u0037\u0031\u0035\u0031\u0029\u007c\u002a\u0030\u0029\u0058\u004f\u0058\u0047\u0055\u005e\u006c\u0077\u0025\u005d\u0052\u0066\u0028\u0061\u0052\u0038\u0071\u0073\u0024\u0076\u004f\u0053\u004d\u0075\u0048\u0063\u0041\u007a\u0043\u0050\u0038\u005d\u002c\u0078\u0054\u0049\u002e\u006b\u0037\u006a\u004a\u0060\u0055\u0032\u0030\u0061\u006b\u004b\u0076\u0078\u0053\u0059\u0028\u0050\u0053\u0033\u003b\u0073\u003f\u004d\u0057\u0031\u0078\u006d\u0036\u0071\u0069\u0050\u007c\u0033\u007a\u004b\u0029\u0068\u005f\u0035\u0049\u0061\u0079\u0029